        {kind:"mcq", q:"Nơi người La Mã cổ đại xem đấu sĩ thi đấu gọi là gì?", opts:["amphitheatre","palace","orchard"], a:0},
        {kind:"gapfill", s:"Andrea Mantegna was a famous ___ artist. (1400-1600)", a:"Renaissance"},
        {kind:"gapfill", s:"Mantua has buildings from ___ times. (500-1400)", a:"medieval"},
        {kind:"classify", word:"vineyard", ctx:"vườn nho", cats:["Nghệ thuật & Kiến trúc","Thiên nhiên & Cảnh quan"], cat:1},
        {kind:"classify", word:"palace", ctx:"cung điện", cats:["Nghệ thuật & Kiến trúc","Thiên nhiên & Cảnh quan"], cat:0},
        {kind:"anagram", clue:"trần nhà", scrambled:"CLEINGI", answer:"ceiling"},
        {kind:"anagram", clue:"vòm cửa", scrambled:"HACR", answer:"arch"},
        {kind:"mcq", q:"Elena đã ban đầu nghĩ chuyến đi sẽ như thế nào?", opts:["Chán (boring)","Vui (fun)","Nguy hiểm (dangerous)"], a:0},
        {kind:"mcq", q:"Ở Verona, Elena đã chọn làm gì vào buổi chiều cuối cùng?", opts:["Đi khám phá thêm Verona thay vì đi xem cửa hàng","Đi ngủ sớm","Về nhà ngay"], a:0}
