CG9.addLesson({id:"u3-3", unit:3, type:"lesson", src:"3.3. Tho Passive Quest - Cambridge Global English 9 Unit 3.3.html", game:{
  storageKey: "tho-quest-cge9-u33-v1",
  brand: "Thỏ Passive Quest",
  subtitle: "Cambridge Global English 9 – Unit 3.3 How was your holiday?",
  mapTitle: "🧳 Bản đồ phiêu lưu: Kỳ nghỉ không suôn sẻ",
  mapIntro: "Cùng Thỏ học thì quá khứ tiếp diễn bị động (past continuous passive) và thêm cụm động từ mới — Unit 3.3, Cambridge Global English 9. Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ dựa theo Cambridge Global English Learner's Book 9 (2nd ed.), Unit 3 Tourism, bài 3.3 \"How was your holiday?\". Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Unit 3.3 – How was your holiday?",
  unlockAll: true,
  vocab: [
    {term:"get off to a bad start", vi:"khởi đầu không suôn sẻ", ex:"Francisco's holiday got off to a bad start."},
    {term:"pick someone up", vi:"đón ai đó", ex:"We were picked up from the airport by a taxi."},
    {term:"turn up", vi:"xuất hiện, đến nơi", ex:"The taxi didn't turn up on time."},
    {term:"hang out", vi:"đi chơi, tụ tập cùng nhau", ex:"Li liked hanging out at the beach."},
    {term:"take off", vi:"cất cánh (máy bay)", ex:"The plane didn't take off until 11.30 at night."},
    {term:"turn back", vi:"quay lại (giữa chừng)", ex:"We had to turn back because of the storm."},
    {term:"get in", vi:"đến nơi, về đến (phương tiện)", ex:"The plane didn't get in until very late."},
    {term:"break down", vi:"hỏng, chết máy (xe cộ)", ex:"The car broke down in a village."},
    {term:"turn out", vi:"hoá ra là", ex:"The holiday turned out to be a lot of fun."},
    {term:"inconsistency", vi:"sự mâu thuẫn, không nhất quán", ex:"There is an inconsistency in what Francisco says."}
  ],
  grammarNotes: [
    {title:"Thì quá khứ tiếp diễn bị động (past continuous passive)", body:"Cấu trúc: was/were + being + V3.\nSo sánh:\n• Quá khứ tiếp diễn chủ động: The car broke down in a village while we were going to Paradise Valley.\n• Quá khứ đơn bị động: We were invited into the house of one of the people in the village.\n• Quá khứ tiếp diễn BỊ ĐỘNG: ...while the car was being fixed. (Ai đó đang sửa xe, và xe là đối tượng bị tác động.)"}
  ],
  levels: [
    {id:1, icon:"🔧", vn:"Nối cụm động từ về du lịch", en:"Match travel multi-word verbs", blocks:[
      {kind:"match", title:"🔧 Nối cụm động từ với nghĩa tiếng Việt", instr:"", pairs:[
        {left:"get off to a bad start", right:"khởi đầu không suôn sẻ"},
        {left:"pick someone up", right:"đón ai đó"},
        {left:"turn up", right:"xuất hiện, đến nơi"},
        {left:"hang out", right:"đi chơi, tụ tập cùng nhau"},
        {left:"take off", right:"cất cánh (máy bay)"},
        {left:"turn back", right:"quay lại giữa chừng"},
        {left:"get in", right:"đến nơi, về đến"},
        {left:"break down", right:"hỏng, chết máy"},
        {left:"turn out", right:"hoá ra là"},
        {left:"inconsistency", right:"sự mâu thuẫn, không nhất quán"}
      ]}
    ]},
    {id:2, icon:"❓", vn:"Trắc nghiệm cụm động từ", en:"Multi-word verb multiple choice", blocks:[
      {kind:"mcq", title:"❓ Chọn từ đúng nhất", instr:"", questions:[
        {q:"Their holiday ______ when the flight was delayed by three hours.", opts:["got off to a bad start","turned up","hung out"], a:0},
        {q:"The plane didn't ______ until 11.30 at night, so they arrived very late.", opts:["get in","take off","break down"], a:0},
        {q:"We waited an hour, but the taxi never ______.", opts:["turned up","broke down","hung out"], a:0},
        {q:"On holiday, Li liked to ______ at the beach with new friends.", opts:["hang out","turn back","get off"], a:0},
        {q:"Our car ______ in a small village, so we had to wait for help.", opts:["broke down","took off","turned up"], a:0},
        {q:"We ______ because of a dangerous storm on the mountain.", opts:["turned back","hung out","picked up"], a:0},
        {q:"The trip ______ to be much better than we expected!", opts:["turned out","broke down","got off"], a:0},
        {q:"There was an ______ in what he said — his story didn't quite match.", opts:["inconsistency","inconvenience","incompetence"], a:0}
      ]}
    ]},
    {id:3, icon:"⚙️", vn:"Lý thuyết: Quá khứ tiếp diễn bị động", en:"Grammar: past continuous passive", blocks:[
      {kind:"theory", title:"⚙️ was/were + being + V3", instr:"", html:"So sánh 3 dạng:<br>• Quá khứ tiếp diễn chủ động: <i>The car <b>broke down</b> in a village while we <b>were going</b> to Paradise Valley.</i><br>• Quá khứ đơn bị động: <i>We <b>were invited</b> into the house of one of the people in the village.</i><br>• Quá khứ tiếp diễn BỊ ĐỘNG: <i>...while the car <b>was being fixed</b>.</i>"},
      {kind:"mcq", title:"⚙️ Câu nào là quá khứ tiếp diễn BỊ ĐỘNG?", instr:"", questions:[
        {q:"Câu nào là quá khứ tiếp diễn bị động?", opts:["The bags were being checked when we arrived.","We were checking the bags.","We checked the bags."], a:0},
        {q:"Câu nào là quá khứ tiếp diễn bị động?", opts:["The car was being repaired all afternoon.","The car broke down.","We were repairing the car."], a:0},
        {q:"Câu nào là quá khứ tiếp diễn bị động?", opts:["Dinner was being prepared while we waited.","We were preparing dinner.","Dinner was prepared."], a:0}
      ]}
    ]},
    {id:4, icon:"✍️", vn:"Chuyển câu sang bị động", en:"Transform to past continuous passive", blocks:[
      {kind:"transform", title:"✍️ Viết lại câu ở dạng quá khứ tiếp diễn bị động", instr:"Dùng was/were being + quá khứ phân từ (V3).", items:[
        {s:"Someone was fixing the car while we waited. →\n______", root:"WAS BEING", a:"The car was being fixed while we waited."},
        {s:"Someone was preparing the dinner while the guests arrived. →\n______", root:"WAS BEING", a:"The dinner was being prepared while the guests arrived."},
        {s:"Someone was checking our passports at the airport. →\n______", root:"WERE BEING", a:"Our passports were being checked at the airport."},
        {s:"Someone was cleaning the hotel room when we came back. →\n______", root:"WAS BEING", a:"The hotel room was being cleaned when we came back."},
        {s:"Someone was building the new road while we drove past. →\n______", root:"WAS BEING", a:"The new road was being built while we drove past."}
      ]}
    ]},
    {id:5, icon:"🎭", vn:"Đúng hay Sai: Chuyện đã xảy ra", en:"True or False: what happened", blocks:[
      {kind:"theory", title:"🎭 Ba câu chuyện kỳ nghỉ (Coursebook trang 60-61)", instr:"", html:"<b>Francisco:</b> Chuyến bay bị trì hoãn, khởi đầu không suôn sẻ, máy bay không cất cánh cho tới 11:30 tối.<br><b>Li:</b> Không thể dùng hồ bơi ở căn hộ tại San Francisco; nghe thông báo trên radio khi đang lái xe tới Yosemite.<br><b>Sasha:</b> Đi tới Agadir (Morocco); xe bị hỏng (break down) trên đường tới Paradise Valley nhưng lại được mời vào nhà người dân trong làng trong lúc xe đang được sửa."},
      {kind:"tf", title:"✅ Đúng hay Sai?", instr:"", items:[
        {s:"Chuyến bay của Francisco khởi đầu rất suôn sẻ, không có vấn đề gì.", a:false},
        {s:"Xe của Sasha bị hỏng trên đường tới Paradise Valley.", a:true},
        {s:"Trong lúc xe đang được sửa, Sasha và gia đình được mời vào nhà một người dân trong làng.", a:true},
        {s:"Li gặp vấn đề khi ở San Francisco, không thể dùng hồ bơi ở căn hộ.", a:true}
      ]}
    ]},
    {id:6, icon:"✍️", vn:"Viết câu về kỳ nghỉ dùng cụm động từ", en:"Write sentences using multi-word verbs", blocks:[
      {kind:"writing", title:"✍️ Viết 1 câu cho mỗi cụm động từ", instr:"Viết về Francisco, Li hoặc Sasha (hoặc tưởng tượng), dùng cụm động từ cho sẵn.", tasks:[
        {prompt:"get off to a bad start", sample:"Francisco's holiday got off to a bad start when the flight was delayed."},
        {prompt:"hang out", sample:"Li liked hanging out with new friends at the beach in San Francisco."},
        {prompt:"break down", sample:"Sasha's car broke down on the way to Paradise Valley."},
        {prompt:"turn out", sample:"In the end, the holiday turned out to be really enjoyable."}
      ]}
    ]},
    {id:7, icon:"😄", vn:"Kể về một kỳ nghỉ trục trặc", en:"Describe a holiday that went wrong", blocks:[
      {kind:"theory", title:"😄 Gợi ý", instr:"", html:"Kể một câu chuyện về kỳ nghỉ có ít nhất 1 điều không suôn sẻ. Bạn có thể bịa ra chi tiết và làm nó hài hước! Cố gắng dùng cụm động từ đã học và ít nhất 1 câu ở dạng quá khứ tiếp diễn bị động."},
      {kind:"writing", title:"✍️ Viết 3-4 câu kể chuyện", instr:"", tasks:[
        {prompt:"Viết 1 câu chuyện ngắn (có thể tưởng tượng) về 1 kỳ nghỉ có sự cố xảy ra.", sample:"Our holiday got off to a bad start because our taxi never turned up. Then, on the way to the airport, our car broke down while it was raining heavily! While the car was being fixed, we had a picnic by the road. In the end, it turned out to be a really funny story to tell."}
      ]}
    ]},
    {id:8, icon:"🗣️", vn:"Luyện nói: Kỳ nghỉ đáng nhớ", en:"Speaking: a memorable holiday", blocks:[
      {kind:"speaking", title:"🗣️ Thẻ luyện nói", instr:"", cards:[
        {q:"Have you ever had a holiday that got off to a bad start? What happened?", vi:"Em từng có kỳ nghỉ khởi đầu không suôn sẻ chưa? Chuyện gì đã xảy ra?", sample:"Yes, once our flight was delayed for five hours!"},
        {q:"Would Francisco, Li or Sasha be the best person to go on holiday with? Why?", vi:"Em nghĩ nên đi nghỉ cùng Francisco, Li hay Sasha? Vì sao?", sample:"I think Sasha, because even when things went wrong, the holiday turned out well."},
        {q:"For some people, going somewhere new is exciting. For others, it's scary. What's your view?", vi:"Với một số người, đi đến nơi mới rất thú vị; với người khác lại đáng sợ. Em nghĩ sao?", sample:"I think it's exciting because you learn about different cultures and ways of life."}
      ]}
    ]},
    {id:9, icon:"👑", vn:"Trận Boss: Tổng ôn tập Unit 3.3", en:"Boss battle: Unit 3.3 review", blocks:[
      {kind:"boss", title:"👑 Trận Boss: Tổng ôn tập Unit 3.3", instr:"", items:[
        {kind:"mcq", q:"'break down' (về xe cộ) nghĩa là gì?", opts:["hỏng, chết máy","cất cánh","đến nơi"], a:0},
        {kind:"mcq", q:"'turn out' nghĩa là gì?", opts:["hoá ra là","quay lại","đi chơi"], a:0},
        {kind:"gapfill", s:"The plane didn't take ___ until 11.30 at night.", a:"off"},
        {kind:"gapfill", s:"The taxi never ___ up, so we missed the bus.", a:"turned"},
        {kind:"transform", s:"Someone was fixing the car. → The car ______ fixed.", root:"WAS BEING", a:"was being"},
        {kind:"mcq", q:"Câu nào đúng là quá khứ tiếp diễn bị động?", opts:["The dinner was being cooked when we arrived.","The dinner was cooked.","We were cooking dinner."], a:0},
        {kind:"anagram", clue:"sự mâu thuẫn, không nhất quán", scrambled:"ISTCONNCYSNIE", answer:"inconsistency"},
        {kind:"choice2", s:"We ___ back because of the storm.", options:["turned","took"], a:"turned"},
        {kind:"mcq", q:"Xe của Sasha bị hỏng ở đâu?", opts:["Trên đường tới Paradise Valley","Ở sân bay","Ở khách sạn"], a:0}
      ]}
    ]}
  ]
}});
