    {term:"local produce", vi:"sản phẩm/nông sản địa phương", ex:"Eating local produce helps local farmers."},
    {term:"souvenirs", vi:"quà lưu niệm", ex:"Buy handmade souvenirs to support local craftspeople."},
    {term:"wildlife products", vi:"sản phẩm từ động vật hoang dã", ex:"Don't buy wildlife products made from endangered species."},
    {term:"endangered species", vi:"loài có nguy cơ tuyệt chủng", ex:"Some souvenirs are made from endangered species."},
    {term:"environmentally sensitive", vi:"nhạy cảm về môi trường (dễ bị tổn hại)", ex:"National parks are often environmentally sensitive places."},
    {term:"family-run", vi:"do gia đình điều hành", ex:"We stayed at a small, family-run hotel."},
    {term:"big-name", vi:"thương hiệu lớn, nổi tiếng", ex:"Big-name hotel chains aren't always good for the local economy."},
    {term:"homemade", vi:"tự làm tại nhà", ex:"We tried some homemade bread at the local market."},
    {term:"open-minded", vi:"cởi mở, dễ tiếp thu cái mới", ex:"Being open-minded helps you enjoy new cultures."},
    {term:"locally made", vi:"được sản xuất tại địa phương", ex:"We bought some locally made pottery as a souvenir."},
    {term:"handmade", vi:"làm bằng tay, thủ công", ex:"The handmade souvenirs help local traditions survive."}
