        {q:"What must entrants send with their photo?", opts:["A title and a supporting statement of up to 100 words","A video explaining the photo","Nothing else is needed"], a:0},
        {q:"In Mei's example photo statement, what does the photo show?", opts:["A plum tree with snow, near her house","A mountain in winter","A pet cat"], a:0}
