        {kind:"gapfill", s:"You are going to do a ___ of the rules of a game.", a:"presentation"},
        {kind:"classify", word:"Look up the rules and write a simple explanation.", ctx:"", cats:["Project 1","Project 2"], cat:0},
        {kind:"classify", word:"Write a title and a supporting statement.", ctx:"", cats:["Project 1","Project 2"], cat:1},
        {kind:"gapfill", s:"Write a ___ ___ of your entry after getting comments.", a:"final version"},
        {kind:"mcq", q:"Boccia là môn thể thao gì?", opts:["Một môn thể thao Paralympic","Một cuộc thi ảnh","Một môn nấu ăn"], a:0},
        {kind:"anagram", clue:"bản nháp", scrambled:"TDARF", answer:"draft"},
        {kind:"gapfill", s:"You are not allowed to change the image by using a computer ___.", a:"program"}
