CG9.addLesson({id:"u8-8", unit:8, type:"lesson", src:"Tho Du An Xanh Quest - Cambridge Global English 9 Unit 8.8.html", game:{
  storageKey: "tho-quest-cge9-u88-v1",
  brand: "Thỏ Dự Án Xanh Quest",
  subtitle: "Cambridge Global English 9 – Unit 8.8 Project challenge",
  mapTitle: "🌳 Bản đồ phiêu lưu: Dự án sống xanh",
  mapIntro: "Cùng Thỏ làm 2 dự án: liệt kê ý tưởng sống bền vững, và lên kế hoạch quy hoạch thành phố bền vững — Unit 8.8, Cambridge Global English 9. Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ dựa theo Cambridge Global English Learner's Book 9 (2nd ed.), Unit 8 The environment, bài 8.8 \"Project challenge\". Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Unit 8.8 – Project challenge",
  unlockAll: true,
  vocab: [
    {term:"sustainable living", vi:"lối sống bền vững", ex:"Compile a list of your five favourite ideas for sustainable living."},
    {term:"to redevelop", vi:"tái phát triển, cải tạo (khu vực)", ex:"Your city is going to redevelop an area near your school."},
    {term:"disused", vi:"bị bỏ hoang, không còn sử dụng", ex:"The disused factories and empty warehouses will be repurposed."},
    {term:"local community", vi:"cộng đồng địa phương", ex:"We are inviting the local community to take part in planning the redevelopment."},
    {term:"renewable energy generation", vi:"tạo ra năng lượng tái tạo", ex:"Renewable energy generation is one option for the new area."},
    {term:"secure bike park facility", vi:"bãi đỗ xe đạp an toàn", ex:"Safe cycle tracks and a secure bike park facility encourage cycling."},
    {term:"cycle track", vi:"đường dành cho xe đạp", ex:"Safe cycle tracks around the area make cycling safer."},
    {term:"vertical farming area", vi:"khu vực canh tác theo chiều dọc", ex:"The plan includes vertical farming areas to grow food locally."}
  ],
  grammarNotes: [
    {title:"Project 1: Sustainable living", body:"Bước 1: Brainstorm ý tưởng theo nhóm nhỏ (cắt giảm nhựa dùng một lần, tránh bao bì không phân huỷ, ủ phân rác hữu cơ, giảm khí thải, tự trồng rau quả, tái sử dụng/tái chế đồ, làm tình nguyện). Bước 2: Chọn 5 ý tưởng. Bước 3: Chuẩn bị trình bày, nêu lý do cho mỗi lựa chọn. Bước 4: Phân công ai trình bày ý nào. Bước 5: Trình bày trước lớp."},
    {title:"Project 2: Sustainable city planning", body:"Thành phố sắp cải tạo (redevelop) một khu công nghiệp cũ gần trường. Hội đồng thành phố mời cộng đồng (bao gồm trường học) góp ý quy hoạch. Chọn 5 ý tưởng từ danh sách (công viên, trung tâm thể thao, quán cà phê, toà nhà trung hoà carbon, rạp chiếu phim, không gian văn phòng, trạm giao thông công cộng, thùng tái chế, năng lượng tái tạo, vườn trên mái, đường xe đạp an toàn, không gian cho cửa hàng nhỏ, khu canh tác theo chiều dọc), viết danh sách kèm lý do."}
  ],
  levels: [
    {id:1, icon:"🌳", vn:"Nối từ vựng dự án sống xanh", en:"Match project vocabulary", blocks:[
      {kind:"match", title:"🌳 Nối từ với nghĩa tiếng Việt", instr:"Bấm 1 từ bên trái, rồi bấm nghĩa đúng bên phải.", pairs:[
        {left:"sustainable living", right:"lối sống bền vững"},
        {left:"to redevelop", right:"tái phát triển, cải tạo (khu vực)"},
        {left:"disused", right:"bị bỏ hoang, không còn sử dụng"},
        {left:"local community", right:"cộng đồng địa phương"},
        {left:"renewable energy generation", right:"tạo ra năng lượng tái tạo"},
        {left:"secure bike park facility", right:"bãi đỗ xe đạp an toàn"},
        {left:"cycle track", right:"đường dành cho xe đạp"},
        {left:"vertical farming area", right:"khu vực canh tác theo chiều dọc"}
      ]}
    ]},
    {id:2, icon:"❓", vn:"Trắc nghiệm từ vựng", en:"Multiple choice: vocabulary", blocks:[
      {kind:"mcq", title:"❓ Chọn đáp án đúng", instr:"", questions:[
        {q:"'Disused' buildings are buildings that are...", opts:["no longer used","brand new","very tall"], a:0},
        {q:"'To redevelop' an area means to...", opts:["change and improve it for a new purpose","destroy it completely and leave it empty","paint the buildings a new colour"], a:0},
        {q:"'Sustainable living' means living in a way that...", opts:["can continue without harming the environment","costs as little money as possible","is very modern and technological"], a:0},
        {q:"The 'local community' refers to...", opts:["the people who live in a particular area","only the city council","only school students"], a:0},
        {q:"'Renewable energy' comes from sources such as...", opts:["solar, wind and hydro power","coal and oil","plastic waste"], a:0}
      ]}
    ]},
    {id:3, icon:"🗳️", vn:"Lý thuyết: Project 1 — Sống bền vững", en:"Theory: Project 1 — Sustainable living", blocks:[
      {kind:"theory", title:"🗳️ Các bước làm Project 1", instr:"", html:"1) Làm việc nhóm nhỏ, brainstorm ý tưởng: cắt giảm nhựa dùng một lần, tránh bao bì không phân huỷ, ủ phân rác hữu cơ, giảm khí thải, tự trồng rau quả, tái sử dụng/tái chế đồ, làm tình nguyện.<br>2) Chọn 5 ý tưởng yêu thích nhất.<br>3) Chuẩn bị danh sách trình bày, nêu lý do cho mỗi lựa chọn.<br>'We think it's a good idea to try making your own fruit juices and smoothies. They'll be delicious and you'll avoid buying juices in plastic bottles.'"},
      {kind:"gapfill", title:"🗳️ Điền từ đúng", instr:"", items:[
        {pre:"Work in small groups and", post:"(brainstorm) ideas for sustainable living.", answers:["brainstorm"]},
        {pre:"Decide which five ideas to", post:"(include) in your list.", answers:["include"]},
        {pre:"Prepare the list, giving", post:"(reasons) for your choices.", answers:["reasons"]},
        {pre:"Give your presentation to the rest of the", post:"(class).", answers:["class"]}
      ]}
    ]},
    {id:4, icon:"🏙️", vn:"Đọc: Project 2 — Quy hoạch thành phố bền vững", en:"Reading: Project 2 — Sustainable city planning", blocks:[
      {kind:"passage", title:"📖 Tóm tắt Project 2", instr:"", text:"Your city is going to redevelop an old industrial area near your school. The disused factories and empty warehouses will be repurposed or replaced for a sustainable future. The city council is inviting the local community, including schools and colleges, to take part in planning the redevelopment, and asks for a list of five ideas with reasons. The list of possible ideas includes: a park with trees and children's play equipment, a sports centre with a swimming pool, cafés with indoor and outdoor seating, carbon-neutral apartment buildings, cinemas and concert rooms, office space and meeting rooms, a public transport system station, recycling bins, renewable energy generation, rooftop gardens, safe cycle tracks with a secure bike park facility, spaces for small businesses, and vertical farming areas."},
      {kind:"classify", title:"📖 Ý tưởng này thuộc PROJECT 1 (sống bền vững cá nhân) hay PROJECT 2 (quy hoạch thành phố)?", instr:"", cats:["Project 1: Sống bền vững","Project 2: Quy hoạch thành phố"], items:[
        {word:"composting green waste", ctx:"", cat:0},
        {word:"growing your own fruit and vegetables", ctx:"", cat:0},
        {word:"carbon-neutral apartment buildings", ctx:"", cat:1},
        {word:"a public transport system station", ctx:"", cat:1},
        {word:"being a volunteer in a community project", ctx:"", cat:0},
        {word:"vertical farming areas", ctx:"", cat:1}
      ]}
    ]},
    {id:5, icon:"💡", vn:"Lý thuyết: chuẩn bị bài trình bày dự án", en:"Theory: preparing your project presentation", blocks:[
      {kind:"theory", title:"💡 Chuẩn bị & trình bày dự án", instr:"", html:"Khi chuẩn bị trình bày dự án, hãy: quyết định ai trình bày ý nào, luyện tập trong nhóm, cân nhắc xem có cần chỉnh sửa gì không, quyết định có dùng hình ảnh/ảnh chụp minh hoạ không.<br>Sau khi trình bày, hãy hỏi ý kiến phản hồi (comments and feedback) từ các bạn khác, và suy nghĩ xem những gì đã học ở các bài 8.1–8.6 giúp ích thế nào cho dự án này."},
      {kind:"gapfill", title:"💡 Điền từ đúng", instr:"", items:[
        {pre:"Practise your presentation within the", post:"(group).", answers:["group"]},
        {pre:"Decide if you're going to show any pictures, photos or other", post:"(items).", answers:["items"]},
        {pre:"Give your presentation and ask for comments and", post:"(feedback).", answers:["feedback"]},
        {pre:"Write your list of ideas, giving reasons to", post:"(support) each one.", answers:["support"]}
      ]}
    ]},
    {id:6, icon:"✍️", vn:"Viết danh sách ý tưởng dự án", en:"Writing your project idea list", blocks:[
      {kind:"writing", title:"✍️ Viết câu của riêng em", instr:"", tasks:[
        {prompt:"Viết 1 ý tưởng sống bền vững của riêng em kèm lý do.", sample:"I think we should grow our own vegetables, because it reduces packaging waste and the food is fresher."},
        {prompt:"Viết 1 ý tưởng cho việc quy hoạch thành phố bền vững kèm lý do.", sample:"I would include a park with trees, because green spaces improve air quality and make people happier."},
        {prompt:"Viết 2-3 câu tóm tắt điều em đã học được từ Unit 8 về môi trường.", sample:"I've learnt that small changes, like cutting down on plastic and growing our own food, can really help the environment. Cities can also become more sustainable with electric vehicles and urban forests."}
      ]}
    ]},
    {id:7, icon:"🗣️", vn:"Luyện nói: dự án của em", en:"Speaking: about your project", blocks:[
      {kind:"speaking", title:"🗣️ Thẻ luyện nói", instr:"", cards:[
        {q:"Which do you think were the best ideas your group came up with?", vi:"Em nghĩ ý tưởng nào tốt nhất mà nhóm em đưa ra?", sample:"I think growing our own fruit and vegetables was the best idea, because it's easy to do and really helps reduce waste."},
        {q:"Did the other groups present any good ideas that you hadn't thought of?", vi:"Các nhóm khác có trình bày ý tưởng hay nào mà em chưa nghĩ tới không?", sample:"Yes, one group suggested making a clothes swap, which I thought was a really creative idea."},
        {q:"What should the new redeveloped area include?", vi:"Khu vực được cải tạo mới nên bao gồm những gì?", sample:"I think it should include a park, a public transport station and carbon-neutral buildings."},
        {q:"How might the work you have done on this project be useful to you in the future?", vi:"Công việc em làm trong dự án này có thể hữu ích thế nào cho tương lai của em?", sample:"It helps me think more carefully about sustainability, which is useful for making better choices in my own life."}
      ]}
    ]},
    {id:8, icon:"👑", vn:"Trận Boss: Tổng ôn tập Unit 8.8", en:"Boss battle: Unit 8.8 review", blocks:[
      {kind:"boss", title:"👑 Trận Boss: Tổng ôn tập Unit 8.8", instr:"", items:[
        {kind:"mcq", q:"'Disused' nghĩa là gì?", opts:["bị bỏ hoang, không còn sử dụng","hoàn toàn mới","rất hiện đại"], a:0},
        {kind:"mcq", q:"'To redevelop' nghĩa là gì?", opts:["tái phát triển, cải tạo khu vực","phá huỷ hoàn toàn","sơn lại màu mới"], a:0},
        {kind:"gapfill", s:"Work in small groups and ___ (brainstorm) ideas for sustainable living.", a:"brainstorm"},
        {kind:"classify", word:"composting green waste", ctx:"", cats:["Project 1","Project 2"], cat:0},
        {kind:"classify", word:"carbon-neutral apartment buildings", ctx:"", cats:["Project 1","Project 2"], cat:1},
        {kind:"gapfill", s:"Give your presentation and ask for comments and ___ (feedback).", a:"feedback"},
        {kind:"mcq", q:"'Renewable energy generation' nghĩa là gì?", opts:["tạo ra năng lượng tái tạo","tiêu thụ nhiên liệu hoá thạch","xây nhà cao tầng"], a:0},
        {kind:"anagram", clue:"cộng đồng", scrambled:"YTNUMMOC", answer:"community"},
        {kind:"gapfill", s:"Write your list of ideas, giving reasons to ___ (support) each one.", a:"support"}
      ]}
    ]}
  ]
}});
CG9.addLesson({id:"u1-7", unit:1, type:"lesson", src:"Tho Email Quest - Cambridge Global English 9 Unit 1.7.html", game:{
  storageKey: "tho-quest-cge9-u17-v1",
  brand: "Thỏ Email Quest",
  subtitle: "Cambridge Global English 9 – Unit 1.7 Improve your writing",
  mapTitle: "✉️ Bản đồ phiêu lưu: Viết email cho bạn",
  mapIntro: "Cùng Thỏ khám phá từ vựng và cách viết một email thân mật cho bạn qua thư (penfriend) — Unit 1.7, Cambridge Global English 9. Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ dựa theo Cambridge Global English Learner's Book 9 (2nd ed.), Unit 1 Views and voices, bài 1.7 \"Improve your writing\". Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Unit 1.7 – Improve your writing",
  unlockAll: true,
  vocab: [
    {term:"be in touch", vi:"giữ liên lạc", ex:"It's been a long time since we've been in touch."},
    {term:"wonder (if)", vi:"tự hỏi, không biết liệu", ex:"I wonder if you could help me."},
    {term:"appreciate", vi:"trân trọng, biết ơn", ex:"I'd really appreciate your help with this."},
    {term:"reason", vi:"lý do", ex:"The reason I'm writing is to ask for your help."},
    {term:"in advance", vi:"trước (thời hạn)", ex:"Thank you in advance!"},
    {term:"favour", vi:"sự giúp đỡ, ân huệ", ex:"I'd like to ask you a favour."},
    {term:"penfriend", vi:"bạn qua thư", ex:"Write an email to a penfriend in another country."},
    {term:"informal", vi:"(văn phong) thân mật, không trang trọng", ex:"The tone of the email is informal and friendly."},
    {term:"looking forward to", vi:"mong chờ", ex:"Looking forward to hearing from you."}
  ],
  grammarNotes: [
    {title:"Cấu trúc một email thân mật", body:"Mở đầu: chào hỏi, hỏi thăm, nhắc đã lâu chưa liên lạc (It's been a long time since we've been in touch).\nNội dung chính: nêu lý do viết thư (Anyway, the reason I'm writing is...) và đưa ra câu hỏi/nhờ vả (I wonder if you could help me by...).\nKết thư: cảm ơn trước (Thank you in advance) và mong hồi âm (Looking forward to hearing from you)."},
    {title:"Một số cụm từ hữu ích", body:"I hope you and your family are well.\nI often wonder how you are and what you are doing.\nI'd really appreciate your help with this.\nThank you in advance!"}
  ],
  levels: [
    {id:1, icon:"✉️", vn:"Nối từ vựng viết email", en:"Match email-writing vocabulary", blocks:[
      {kind:"match", title:"✉️ Nối từ với nghĩa tiếng Việt", instr:"Bấm 1 từ bên trái, rồi bấm nghĩa đúng bên phải.", pairs:[
        {left:"be in touch", right:"giữ liên lạc"},
        {left:"wonder (if)", right:"tự hỏi, không biết liệu"},
        {left:"appreciate", right:"trân trọng, biết ơn"},
        {left:"reason", right:"lý do"},
        {left:"in advance", right:"trước (thời hạn)"},
        {left:"favour", right:"sự giúp đỡ, ân huệ"},
        {left:"penfriend", right:"bạn qua thư"},
        {left:"informal", right:"thân mật, không trang trọng"},
        {left:"looking forward to", right:"mong chờ"}
      ]}
    ]},
    {id:2, icon:"❓", vn:"Trắc nghiệm từ vựng", en:"Multiple choice: vocabulary", blocks:[
      {kind:"mcq", title:"❓ Chọn đáp án đúng", instr:"", questions:[
        {q:"If you 'wonder' something, you...", opts:["ask yourself about it, not sure of the answer","are certain about it","forget about it"], a:0},
        {q:"'Appreciate' means...", opts:["feel grateful for something","feel angry about something","forget something"], a:0},
        {q:"'In advance' means...", opts:["before something happens","after something happens","during something"], a:0},
        {q:"A 'favour' is...", opts:["something kind that you ask someone to do for you","a type of email","a grammar rule"], a:0},
        {q:"A 'penfriend' is...", opts:["a friend you write letters/emails to, often in another country","a friend at your school","a type of pen"], a:0},
        {q:"'Informal' writing is...", opts:["friendly and relaxed in style","very serious and businesslike","written only in capital letters"], a:0},
        {q:"'Looking forward to' means...", opts:["feeling excited about something that will happen","feeling worried about the past","feeling bored"], a:0}
      ]}
    ]},
    {id:3, icon:"📧", vn:"Cấu trúc email: mở đầu & lý do viết", en:"Email structure: opening & reason", blocks:[
      {kind:"theory", title:"📧 Mở đầu một email thân mật", instr:"", html:"Mở đầu: <i>I hope you and your family are well. It's been a long time since we've been in touch.</i><br>Nêu lý do viết thư: <i>Anyway, the reason I'm writing is to ask you for some help with...</i>"},
      {kind:"gapfill", title:"📧 Điền từ còn thiếu", instr:"", items:[
        {pre:"Hello Lily! I hope you and your family are", post:".", answers:["well"]},
        {pre:"The", post:"I'm writing is to ask you for some help.", answers:["reason"]},
        {pre:"I", post:"if you could help me by answering these questions.", answers:["wonder"]},
        {pre:"I'd really", post:"your help with this.", answers:["appreciate"]}
      ]}
    ]},
    {id:4, icon:"📩", vn:"Đọc: email của Céline gửi Lily", en:"Reading: Céline's email to Lily", blocks:[
      {kind:"passage", title:"📩 Tóm tắt nội dung email", instr:"", text:"Céline wrote an email to her old friend Lily. She started by saying hello and explaining that it had been a long time since they were in touch. She asked how Lily and her family were, and whether Lily was still doing her art classes.\n\nThen Céline explained the reason she was writing: she was doing a creative writing course, and she was writing a short story about what it's like to be someone of her age. She wanted to find out how older people are seen in different countries, so she asked Lily three questions: Are there stereotypes of older people in her country? How are older people shown in the media? Does Lily still have a role model, and is that person younger than her?\n\nAt the end, Céline thanked Lily in advance for her help and said she was looking forward to hearing from her soon."},
      {kind:"classify", title:"📩 Phần này thuộc mục nào của email?", instr:"", cats:["Mở đầu","Nội dung chính","Kết thư"], items:[
        {word:"explaining it had been a long time since they were in touch", ctx:"", cat:0},
        {word:"asking how Lily and her family were", ctx:"", cat:0},
        {word:"explaining the reason she was writing", ctx:"", cat:1},
        {word:"asking three questions about older people", ctx:"", cat:1},
        {word:"thanking Lily in advance", ctx:"", cat:2},
        {word:"looking forward to hearing from her soon", ctx:"", cat:2}
      ]}
    ]},
    {id:5, icon:"🖊️", vn:"Cấu trúc email: kết thư", en:"Email structure: closing", blocks:[
      {kind:"theory", title:"🖊️ Kết thư một email thân mật", instr:"", html:"Cảm ơn trước: <i>I'd really appreciate your help with this. Thank you in advance!</i><br>Mong hồi âm: <i>Looking forward to hearing from you.</i>"},
      {kind:"gapfill", title:"🖊️ Điền từ còn thiếu", instr:"", items:[
        {pre:"Thank you in", post:"!", answers:["advance"]},
        {pre:"Looking forward to", post:"from you.", answers:["hearing"]},
        {pre:"I haven't heard from you for", post:".", answers:["ages"]},
        {pre:"Anyway, I'd like to ask you a", post:".", answers:["favour"]}
      ]}
    ]},
    {id:6, icon:"✍️", vn:"Viết email cho bạn qua thư", en:"Writing an email to a penfriend", blocks:[
      {kind:"writing", title:"✍️ Viết câu của riêng em", instr:"", tasks:[
        {prompt:"Viết phần mở đầu email cho một người bạn qua thư (penfriend), hỏi thăm và nhắc đã lâu chưa liên lạc.", sample:"Dear Alex, I hope you and your family are well. It's been a long time since we've been in touch!"},
        {prompt:"Viết 1 câu nêu lý do em viết email, dùng cụm 'the reason I'm writing is...'", sample:"The reason I'm writing is to ask for your help with a school project about teenage life."},
        {prompt:"Viết phần kết thư, dùng 'Looking forward to hearing from you' và cảm ơn trước.", sample:"Thank you in advance for your help. Looking forward to hearing from you soon!"}
      ]}
    ]},
    {id:7, icon:"🗨️", vn:"Luyện nói: Chủ đề trong email", en:"Speaking: topics from the email", blocks:[
      {kind:"speaking", title:"🗨️ Thẻ luyện nói", instr:"", cards:[
        {q:"Are there stereotypes of older people in your country? What are they?", vi:"Có định kiến gì về người lớn tuổi ở nước em không?", sample:"Some people think older people don't understand technology, but that's not always true."},
        {q:"How are older people shown in the media?", vi:"Người lớn tuổi được thể hiện thế nào trên truyền thông?", sample:"Sometimes they're shown as wise, but sometimes the media only shows negative stereotypes."},
        {q:"Do you have a role model who is older than you?", vi:"Em có thần tượng nào lớn tuổi hơn mình không?", sample:"Yes, my grandmother is my role model because she's very wise and caring."},
        {q:"Why is it a good idea to have a penfriend in another country?", vi:"Vì sao nên có bạn qua thư ở nước khác?", sample:"It helps you learn about different cultures and practise your English."}
      ]}
    ]},
    {id:8, icon:"👑", vn:"Trận Boss: Tổng ôn tập Unit 1.7", en:"Boss battle: Unit 1.7 review", blocks:[
      {kind:"boss", title:"👑 Trận Boss: Tổng ôn tập Unit 1.7", instr:"", items:[
        {kind:"mcq", q:"'appreciate' nghĩa là gì?", opts:["trân trọng, biết ơn","tự hỏi","giữ liên lạc"], a:0},
        {kind:"mcq", q:"'penfriend' nghĩa là gì?", opts:["bạn qua thư","bạn cùng lớp","người lạ"], a:0},
        {kind:"gapfill", s:"The ___ I'm writing is to ask for your help.", a:"reason"},
        {kind:"gapfill", s:"Looking forward to ___ from you.", a:"hearing"},
        {kind:"classify", word:"asking how Lily and her family were", ctx:"", cats:["Mở đầu","Nội dung chính","Kết thư"], cat:0},
        {kind:"classify", word:"thanking Lily in advance", ctx:"", cats:["Mở đầu","Nội dung chính","Kết thư"], cat:2},
        {kind:"anagram", clue:"sự giúp đỡ, ân huệ", scrambled:"UROVAF", answer:"favour"},
        {kind:"anagram", clue:"thân mật, không trang trọng", scrambled:"MLOFRANI", answer:"informal"},
        {kind:"mcq", q:"'in advance' nghĩa là gì?", opts:["trước (thời hạn)","sau khi xong việc","ngay lúc đó"], a:0}
      ]}
    ]}
  ]
}});
CG9.addLesson({id:"u2-2", unit:2, type:"lesson", src:"Tho Food Quest II - Cambridge Global English 9 Unit 2.2.html", game:{
  storageKey: "tho-quest-cge9-u22-v1",
  brand: "Thỏ Food Quest II",
  subtitle: "Cambridge Global English 9 – Unit 2.2 Food for thought",
  mapTitle: "🧠 Bản đồ phiêu lưu: Food for Thought 🏃",
  mapIntro: "Cùng Thỏ khám phá mối liên hệ giữa ăn uống, tập thể dục và sức khoẻ — Unit 2.2, Cambridge Global English 9. Không tính giờ, sai bao nhiêu lần cũng được!",
  footer: "Tự soạn cho bé Thỏ dựa theo Cambridge Global English Learner's Book 9 &amp; Workbook 9 (2nd ed.), Unit 2.2 \"Food for thought\". Tiến độ lưu trên trình duyệt này.",
  notebookTitle: "📖 Sổ tay Unit 2.2 – Food for thought",
  vocab: [
    {term:"bacteria", vi:"vi khuẩn", ex:"Antibiotics can kill harmful bacteria."},
    {term:"cells", vi:"tế bào", ex:"The human body is made up of billions of cells."},
    {term:"diabetes", vi:"bệnh tiểu đường", ex:"Eating too much sugar can increase the risk of diabetes."},
    {term:"disease", vi:"bệnh, dịch bệnh", ex:"Regular exercise can help prevent heart disease."},
    {term:"immune system", vi:"hệ miễn dịch", ex:"Moderate exercise helps your immune system fight off illness."},
    {term:"infection", vi:"sự nhiễm trùng", ex:"Your body needs energy to fight an infection."},
    {term:"recovery", vi:"sự hồi phục", ex:"Your recovery is likely to be slower if you don't rest."},
    {term:"viruses", vi:"vi-rút", ex:"Colds and flu are usually caused by viruses."},
    {term:"skip (a meal)", vi:"bỏ bữa (ăn)", ex:"Skipping meals leads to low blood sugar."},
    {term:"restore", vi:"phục hồi, khôi phục", ex:"A carbohydrate-based breakfast helps restore blood sugar levels."},
    {term:"crave", vi:"thèm (một cách mãnh liệt)", ex:"If you skip meals, you're likely to crave sweet, carbohydrate-rich snacks."},
    {term:"suppress", vi:"ức chế, kìm nén", ex:"Too much exercise can suppress the immune system."},
    {term:"susceptible (to)", vi:"dễ bị ảnh hưởng bởi", ex:"Too much exercise makes the body more susceptible to illness."}
  ],
  grammarNotes: [
    {title:"Comparative adjectives and adverbs (So sánh hơn)", body:"Tính từ ngắn: thêm <b>-er</b> (slow→slower). Tính từ dài: dùng <b>more</b> + tính từ (efficient→more efficient). Trạng từ: dùng <b>more</b> + trạng từ (quickly→more quickly). <br>So sánh KÉM hơn: dùng <b>less</b> trước tính từ/trạng từ (less tired, less likely, less efficiently).<br>Bất quy tắc: good→better, bad→worse, well→better, badly→worse, far→farther."}
  ],
  levels: [
    {id:1, icon:"🦠", vn:"Nối nghĩa từ vựng", en:"Match the words with their meanings", blocks:[
      {kind:"match", title:"🦠 Nối từ tiếng Anh với nghĩa tiếng Việt", instr:"Bấm 1 từ bên trái, rồi bấm nghĩa đúng bên phải.", pairs:[
        {left:"bacteria", right:"vi khuẩn"},
        {left:"cells", right:"tế bào"},
        {left:"diabetes", right:"bệnh tiểu đường"},
        {left:"disease", right:"bệnh, dịch bệnh"},
        {left:"immune system", right:"hệ miễn dịch"},
        {left:"infection", right:"sự nhiễm trùng"},
        {left:"recovery", right:"sự hồi phục"},
        {left:"viruses", right:"vi-rút"},
        {left:"skipping (a meal)", right:"không ăn (bữa ăn) như bình thường"},
        {left:"restore", right:"đưa trở về trạng thái tốt"},
        {left:"crave", right:"muốn một thứ gì đó rất nhiều"},
        {left:"suppress", right:"làm cho một thứ ngừng hoạt động tốt"},
        {left:"susceptible", right:"dễ bị ảnh hưởng bởi một thứ gì đó"}
      ]}
    ]},
    {id:2, icon:"❓", vn:"Trắc nghiệm từ vựng", en:"Vocabulary multiple choice", blocks:[
      {kind:"mcq", title:"❓ Chọn từ đúng nhất", instr:"Đọc câu và chọn từ phù hợp nhất.", questions:[
        {q:"Small organisms that can cause food poisoning are called ______.", opts:["bacteria","cells","recovery","diabetes"], a:0},
        {q:"The human body is made up of billions of tiny ______.", opts:["viruses","cells","infections","diseases"], a:1},
        {q:"A disease where the body can't regulate blood sugar is called ______.", opts:["diabetes","infection","recovery","immune system"], a:0},
        {q:"Heart ______ can be caused by an unhealthy diet.", opts:["disease","recovery","virus","cell"], a:0},
        {q:"Your body's ______ helps protect you from illness.", opts:["infection","immune system","diabetes","recovery"], a:1},
        {q:"If bacteria enter a wound, it can cause an ______.", opts:["infection","recovery","cell","virus"], a:0},
        {q:"After being ill, your ______ is likely to be slower if you don't rest.", opts:["recovery","infection","disease","cell"], a:0},
        {q:"Colds and flu are usually caused by ______.", opts:["bacteria","viruses","diabetes","cells"], a:1},
        {q:"If you don't eat breakfast, you are ______ a meal.", opts:["restoring","suppressing","skipping","craving"], a:2},
        {q:"Eating a carbohydrate-based breakfast helps ______ your blood sugar levels.", opts:["restore","crave","suppress","skip"], a:0},
        {q:"If you don't eat regularly, you're likely to ______ sweet, sugary snacks.", opts:["restore","crave","suppress","skip"], a:1},
        {q:"Doing extreme exercise can ______ your immune system.", opts:["restore","crave","suppress","skip"], a:2}
      ]}
    ]},
    {id:3, icon:"📖", vn:"Đọc hiểu 2 đoạn trích", en:"Reading: two magazine extracts", blocks:[
      {kind:"passage", title:"📖 Đoạn trích 1 (Dr Brian Stollery)", instr:"", text:"'Skipping meals leads to low blood sugar, which affects our mood and our ability to think clearly. Our brains use about 20% of the energy used by our bodies. We need to keep up a steady supply of energy so that the brain can do its job.'\n\nIt is particularly important to eat a good carbohydrate-based breakfast to restore blood sugar levels after a night's sleep. You also need to eat regular meals during the day, because if you don't, the level of serotonin in your body drops. Serotonin is the chemical that helps to keep your moods and emotions in balance.\n\nThere is another consequence of skipping meals: you're likely to eat more calories. If you don't eat regularly, your blood sugar levels drop, so you crave sweet, carbohydrate-rich snacks, full of calories. Eating a lot of these snacks can lead to serious health problems such as diabetes or heart disease."},
      {kind:"passage", title:"📖 Đoạn trích 2", instr:"", text:"Studies have found that people who do sport in their free time appear to be healthier and catch coughs and colds less frequently than people who are less active. Moderate exercise helps the immune cells to circulate around the body more quickly and therefore helps to kill bacteria and viruses more efficiently. However, there is also evidence that too much exercise can have the opposite effect. It can suppress the immune system, especially after extreme exercise, making the body more susceptible to illness and less able to fight off disease.\n\nA further point to remember is that if you are ill, you should not exercise too much because your body is already working hard to fight the infection. Putting stress on your system will mean that your recovery is likely to be slower."},
      {kind:"tf", title:"✅ Đúng hay Sai?", instr:"Dựa vào 2 đoạn trích ở trên.", items:[
        {s:"Bỏ bữa ăn có thể khiến chúng ta khó suy nghĩ rõ ràng hơn.", a:true},
        {s:"Theo bài đọc, não bộ sử dụng khoảng 50% năng lượng của cơ thể.", a:false},
        {s:"Ăn sáng với thực phẩm giàu tinh bột giúp phục hồi lượng đường trong máu sau khi ngủ.", a:true},
        {s:"Nếu không ăn đều đặn, ta sẽ thèm ăn rau xanh nhiều hơn.", a:false},
        {s:"Những người tập thể dục thường xuyên thường ít bị cảm cúm hơn.", a:true},
        {s:"Tập thể dục cực độ khi đang ốm sẽ giúp ta hồi phục nhanh hơn.", a:false}
      ]},
      {kind:"mcq", title:"❓ Câu hỏi thêm", instr:"", questions:[
        {q:"Chất hoá học nào giúp giữ cân bằng cảm xúc, theo đoạn trích 1?", opts:["Serotonin","Insulin","Adrenaline"], a:0},
        {q:"Tập thể dục quá mức có thể làm gì với hệ miễn dịch?", opts:["Làm hệ miễn dịch mạnh hơn mãi mãi","Ức chế (suppress) hệ miễn dịch","Không ảnh hưởng gì cả"], a:1},
        {q:"Vì sao không nên tập thể dục nhiều khi đang ốm?", opts:["Vì cơ thể đang phải gắng sức chống lại nhiễm trùng","Vì trời sẽ mưa","Vì bác sĩ không cho phép tập bất cứ lúc nào"], a:0}
      ]}
    ]},
    {id:4, icon:"⚖️", vn:"Ngữ pháp: Dạng so sánh đúng", en:"Grammar: correct comparative form", blocks:[
      {kind:"theory", title:"⚖️ Ôn lại: So sánh hơn", instr:"", html:"Tính từ ngắn: thêm <b>-er</b> (slow→slower). Tính từ/trạng từ dài: dùng <b>more</b> (efficient→more efficient, quickly→more quickly). Một số từ bất quy tắc: well→better, good→better, bad→worse."},
      {kind:"mcq", title:"⚖️ Chọn dạng so sánh đúng", instr:"Chọn cụm từ đúng để hoàn thành câu (dựa theo Workbook).", questions:[
        {q:"My brother isn't a good swimmer, but I am. I can swim ______.", opts:["more well","better","gooder"], a:1},
        {q:"Omar doesn't exercise regularly. I exercise ______ than him.", opts:["more frequent","more frequently","frequently"], a:1},
        {q:"Your homework is too difficult. My homework is ______ than yours.", opts:["less difficult","more easy","easiest"], a:0},
        {q:"My sister isn't good at French, but I am. I can speak French ______ than her.", opts:["more fluent","more fluently","fluentlier"], a:1},
        {q:"We don't get up early at weekends. We get up ______ on weekdays.", opts:["more early","earlier","more earlier"], a:1},
        {q:"After a good night's sleep, you'll be able to think ______.", opts:["clearer","more clearer","more clearly"], a:2},
        {q:"I hope he'll be ______ next time so he doesn't get injured again.", opts:["more careful","more carefully","more carefull"], a:0},
        {q:"She says she can breathe ______ when she gets out of the city.", opts:["easier","more easy","more easily"], a:2},
        {q:"When you eat ______, you feel full sooner.", opts:["more slowly","more slower","slower"], a:0},
        {q:"My grandfather looked much ______ when I saw him last week.", opts:["more healthily","healthy","healthier"], a:2}
      ]}
    ]},
    {id:5, icon:"📉", vn:"So sánh hơn &amp; kém hơn — luyện tập", en:"Comparative practice (more / less)", blocks:[
      {kind:"transform", title:"📉 5A. Hoàn thành câu (theo Coursebook)", instr:"Viết dạng so sánh đúng của từ gốc trong ngoặc.", items:[
        {s:"Potatoes, rice and pasta release energy into the body much ______ than sweet snacks.", root:"SLOW", a:"more slowly"},
        {s:"I wear contact lenses when I play volleyball because I can see ______ with them.", root:"CLEAR", a:"clearer"},
        {s:"People who do regular exercise have a ______ immune system.", root:"STRONG", a:"stronger"},
        {s:"I've started going to bed earlier and I've noticed I'm much ______ at school the next day.", root:"TIRED", a:"less tired"},
        {s:"You're ______ to have mood swings if you're hungry.", root:"LIKELY", a:"more likely"},
        {s:"Students who come to school without having breakfast work ______ during the morning.", root:"EFFICIENT", a:"less efficiently"}
      ]},
      {kind:"transform", title:"📉 5B. Hoàn thành câu (mở rộng, theo Workbook)", instr:"Viết dạng so sánh đúng của từ gốc trong ngoặc.", items:[
        {s:"Maintaining blood sugar levels helps you to work ______.", root:"EFFICIENT", a:"more efficiently"},
        {s:"Exercising regularly means you are ______ to catch a cold.", root:"LIKELY", a:"less likely"},
        {s:"People who eat a healthy diet are ______ to illness.", root:"SUSCEPTIBLE", a:"less susceptible"},
        {s:"Skipping meals means that you eat snacks ______.", root:"FREQUENT", a:"more frequently"},
        {s:"If you do too much exercise when you are ill, you will recover ______.", root:"QUICK", a:"less quickly"}
      ]}
    ]},
    {id:6, icon:"🥗", vn:"Áp dụng: Sofia và Nabil", en:"Apply it: Sofia and Nabil", blocks:[
      {kind:"theory", title:"🥗 Thông tin về Sofia và Nabil", instr:"", html:"<b>Sofia:</b> dậy lúc 6 giờ sáng · đi bộ 20 phút tới trường · ăn trưa salad và táo · ăn trưa trong 25 phút · chơi bóng chuyền 1 lần/tuần.<br><b>Nabil:</b> dậy lúc 7 giờ sáng · đi bộ 10 phút tới trường · ăn trưa pizza và snack khoai tây · ăn trưa trong 15 phút · chạy bộ mỗi ngày."},
      {kind:"transform", title:"🥗 Hoàn thành câu so sánh", instr:"Viết dạng so sánh đúng của từ gốc trong ngoặc, dựa vào thông tin ở trên.", items:[
        {s:"Sofia has a ______ lunch.", root:"HEALTHY", a:"healthier"},
        {s:"Sofia eats lunch ______.", root:"SLOW", a:"more slowly"},
        {s:"Sofia is ______ than Nabil.", root:"ACTIVE", a:"less active"},
        {s:"Nabil's lunch is ______ than Sofia's.", root:"HEALTHY", a:"less healthy"},
        {s:"Nabil eats lunch ______.", root:"QUICK", a:"more quickly"},
        {s:"Nabil is ______ than Sofia.", root:"ACTIVE", a:"more active"}
      ]}
    ]},
    {id:7, icon:"✍️", vn:"Luyện viết", en:"Writing practice", blocks:[
      {kind:"writing", title:"✍️ 1. Đặt câu với mỗi từ sau", instr:"", tasks:[
        {prompt:"Đặt câu với từ: <b>bacteria</b>", sample:"Washing your hands can help stop the spread of harmful bacteria."},
        {prompt:"Đặt câu với từ: <b>immune system</b>", sample:"Eating well and sleeping enough keeps your immune system strong."},
        {prompt:"Đặt câu với từ: <b>infection</b>", sample:"He had to take medicine to treat the infection."},
        {prompt:"Đặt câu với từ: <b>recovery</b>", sample:"Her recovery from the illness took about two weeks."},
        {prompt:"Đặt câu với từ: <b>susceptible</b>", sample:"Tired people are more susceptible to catching colds."}
      ]},
      {kind:"writing", title:"✍️ 2. Trả lời câu hỏi bằng 2-3 câu", instr:"", tasks:[
        {prompt:"Do you think there's a link between eating regular meals and being able to concentrate in class? Why?", sample:"I think there is a link, because if I skip breakfast I feel tired and can't concentrate. Eating regular meals keeps my blood sugar steady, so I think more clearly."}
      ]},
      {kind:"writing", title:"✍️ 3. So sánh thói quen của em với một người bạn", instr:"Viết 2 câu so sánh thói quen ăn uống hoặc tập thể dục của em với một người bạn, dùng dạng so sánh hơn/kém.", tasks:[
        {prompt:"Viết 2 câu so sánh (giống ví dụ Sofia và Nabil).", sample:"I get up earlier than my friend, but she exercises more often than me. My lunch is usually healthier than hers."}
      ]}
    ]},
    {id:8, icon:"🗣️", vn:"Luyện nói", en:"Speaking practice", blocks:[
      {kind:"speaking", title:"🗣️ Thẻ luyện nói", instr:"Đọc câu hỏi, nói to câu trả lời, rồi bấm vào thẻ để xem gợi ý.", cards:[
        {q:"Do you think there's a link between eating regular meals and being able to concentrate in class?", vi:"Em có nghĩ có mối liên hệ giữa việc ăn đều đặn và khả năng tập trung trong lớp không?", sample:"I think there is a link. When I eat regular meals, my blood sugar stays steady and I can concentrate better in class."},
        {q:"Why do some people get impatient or bad-tempered when they're hungry?", vi:"Vì sao một số người trở nên nóng tính khi đói bụng?", sample:"I think it's because low blood sugar affects mood, so people find it harder to stay calm when they're hungry."},
        {q:"'The more exercise you do, the better you feel.' Do you think this is true?", vi:"'Tập càng nhiều thì càng cảm thấy khoẻ hơn.' Em có nghĩ điều này đúng không?", sample:"I think moderate exercise makes you feel better, but too much exercise can actually be bad for your immune system, so more isn't always better."},
        {q:"What kind of breakfast do you usually eat? Is it a healthy choice?", vi:"Em thường ăn sáng gì? Đó có phải lựa chọn lành mạnh không?", sample:"I usually eat eggs and bread for breakfast. I think it's a fairly healthy choice because it gives me energy and protein."}
      ]}
    ]},
    {id:9, icon:"👑", vn:"Boss: Tổng ôn tập", en:"Boss level: mixed review", blocks:[
      {kind:"boss", title:"👑 Trận Boss: Tổng ôn tập Unit 2.2", instr:"Trộn tất cả các dạng bài đã học!", items:[
        {kind:"mcq", q:"Small organisms that can cause disease are called ______.", opts:["bacteria","recovery","diabetes"], a:0},
        {kind:"mcq", q:"Your body's defence against illness is called your ______.", opts:["infection","immune system","recovery"], a:1},
        {kind:"mcq", q:"If you don't eat a meal, you ______ it.", opts:["restore","skip","suppress"], a:1},
        {kind:"mcq", q:"To want something very much is to ______ it.", opts:["crave","suppress","restore"], a:0},
        {kind:"gapfill", s:"After being ill, your ___ is likely to be slower if you don't rest.", a:"recovery"},
        {kind:"gapfill", s:"Colds and flu are usually caused by ___.", a:"viruses"},
        {kind:"transform", s:"People who do regular exercise have a ______ immune system.", root:"STRONG", a:"stronger"},
        {kind:"transform", s:"Skipping meals means that you eat snacks ______.", root:"FREQUENT", a:"more frequently"},
        {kind:"transform", s:"I've noticed I'm much ______ at school when I go to bed early.", root:"TIRED", a:"less tired"},
        {kind:"choice2", s:"My homework is ___ difficult than yours.", options:["less","fewer"], a:"less"},
        {kind:"mcq", q:"After a good night's sleep, you'll be able to think ______.", opts:["clearer","more clearly","more clearer"], a:1},
        {kind:"mcq", q:"According to the reading, what helps restore blood sugar after sleeping?", opts:["A carbohydrate-based breakfast","Extreme exercise","Skipping lunch"], a:0},
        {kind:"mcq", q:"What can too much exercise do to the immune system?", opts:["Suppress it","Make it stronger forever","Nothing at all"], a:0},
        {kind:"gapfill", s:"Sofia has a ___ lunch than Nabil. (use: healthy)", a:"healthier"},
        {kind:"gapfill", s:"Nabil eats lunch more ___ than Sofia. (use: quick)", a:"quickly"},
        {kind:"mcq", q:"Eating a healthy diet makes you ______ to illness.", opts:["more susceptible","less susceptible","more infected"], a:1},
        {kind:"transform", s:"If you do too much exercise when ill, you will recover ______.", root:"QUICK", a:"less quickly"},
        {kind:"mcq", q:"A disease affecting the body's ability to regulate blood sugar is ______.", opts:["diabetes","infection","recovery"], a:0}
      ]}
    ]}
  ]
}});
CG9.addLesson({id:"u4-3", unit:4, type:"lesson", src:"Tho Gen Quest - Cambridge Global English 9 Unit 4.3.html", game:{
  storageKey: "tho-quest-cge9-u43-v1",
  brand: "Thỏ Gen Quest",
  subtitle: "Cambridge Global English 9 – Unit 4.3 What makes us the same? What makes us different?",
  mapTitle: "🧬 Bản đồ phiêu lưu: DNA và gen di truyền",
  mapIntro: "Cùng Thỏ tìm hiểu về DNA, gen di truyền, dấu vân tay, và học thì hiện tại hoàn thành tiếp diễn (present perfect continuous) — Unit 4.3, Cambridge Global English 9. Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ dựa theo Cambridge Global English Learner's Book 9 (2nd ed.), Unit 4 Science, bài 4.3 \"What makes us the same? What makes us different?\". Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Unit 4.3 – DNA and genetics",
  unlockAll: true,
  vocab: [
    {term:"DNA", vi:"a-xít deoxyribonucleic (ADN) — chất hoá học có trong mọi sinh vật sống", ex:"DNA carries the genetic information of every living thing."},
    {term:"gene", vi:"gen — phần của tế bào kiểm soát một đặc điểm cụ thể", ex:"A gene controls a particular characteristic, like eye colour."},
    {term:"genetics", vi:"di truyền học — môn nghiên cứu về gen và các đặc điểm di truyền", ex:"Rian has been learning about genetics in science class."},
    {term:"fingerprints", vi:"dấu vân tay — hoa văn trên đầu ngón tay, là duy nhất ở mỗi người", ex:"Detectives use fingerprints to help solve crimes."},
    {term:"unique", vi:"độc nhất — chỉ có một, không có cái nào giống", ex:"Everyone's fingerprints are unique."},
    {term:"human genome", vi:"bộ gen người — toàn bộ DNA của một người, bao gồm tất cả các gen", ex:"Scientists have mapped the whole human genome."}
  ],
  grammarNotes: [
    {title:"Thì hiện tại hoàn thành tiếp diễn (Present perfect continuous)", body:"Công thức: have/has + been + V-ing.\nDùng để nói về việc bắt đầu trong quá khứ và tiếp diễn đến hiện tại: We've been learning about DNA, genetics and the human genome.\nCũng dùng cho hành động vừa mới xảy ra, để lại kết quả rõ ràng ở hiện tại: They've been playing football. (quần áo lấm bẩn)\nSo sánh: We've been learning about DNA this week. (tiếp diễn, chưa xong) vs Today, we did an experiment. (quá khứ đơn, hành động đã hoàn tất, xác định thời điểm)"}
  ],
  levels: [
    {id:1, icon:"🧬", vn:"Nối từ vựng về DNA và di truyền", en:"Match DNA & genetics vocabulary", blocks:[
      {kind:"match", title:"🧬 Nối từ với nghĩa tiếng Việt", instr:"", pairs:[
        {left:"DNA", right:"a-xít deoxyribonucleic (ADN)"},
        {left:"gene", right:"gen — kiểm soát một đặc điểm cụ thể"},
        {left:"genetics", right:"di truyền học"},
        {left:"fingerprints", right:"dấu vân tay"},
        {left:"unique", right:"độc nhất, không cái nào giống"},
        {left:"human genome", right:"bộ gen người (toàn bộ DNA)"}
      ]}
    ]},
    {id:2, icon:"❓", vn:"Trắc nghiệm: Định nghĩa khoa học", en:"Multiple choice: science definitions", blocks:[
      {kind:"mcq", title:"❓ Từ nào phù hợp với định nghĩa?", instr:"", questions:[
        {q:"'Being the only one of its kind, so there is no other that is the same' describes which word?", opts:["unique","gene","genome"], a:0},
        {q:"'A chemical which is present in all living organisms' describes:", opts:["DNA","fingerprints","genetics"], a:0},
        {q:"'The part of a cell that controls particular characteristics' describes:", opts:["gene","genome","genetics"], a:0},
        {q:"'The complete set of DNA for a human, including all of its genes' describes:", opts:["human genome","gene","fingerprint"], a:0},
        {q:"'The mark made by a person's fingertips, which has a unique pattern' describes:", opts:["fingerprints","genes","DNA"], a:0},
        {q:"'The study of genes and inherited characteristics' describes:", opts:["genetics","genome","fingerprints"], a:0}
      ]}
    ]},
    {id:3, icon:"⚙️", vn:"Ngữ pháp: Hiện tại hoàn thành tiếp diễn", en:"Grammar: present perfect continuous", blocks:[
      {kind:"theory", title:"⚙️ have/has been + V-ing", instr:"", html:"Dùng <b>hiện tại hoàn thành tiếp diễn</b> cho việc bắt đầu trong quá khứ và còn tiếp diễn: <i>We've <b>been learning</b> about DNA this week.</i><br>Cũng dùng khi hành động vừa xảy ra, để lại kết quả rõ ràng: <i>They've <b>been playing</b> football.</i> (quần áo lấm bẩn)"},
      {kind:"gapfill", title:"⚙️ Hoàn thành câu với have/has been + V-ing", instr:"", items:[
        {pre:"We", post:"about DNA and genetics all week. (learn)", answers:["have been learning","'ve been learning"]},
        {pre:"Rian", post:"a lot about genes recently. (find out)", answers:["has been finding out"]},
        {pre:"Look at your hands! You", post:". Your hands are covered in paint! (paint)", answers:["have been painting","'ve been painting"]},
        {pre:"In science this term, we", post:"experiments about fingerprints. (do)", answers:["have been doing"]}
      ]}
    ]},
    {id:4, icon:"👨‍👩‍👧", vn:"Bài đọc: Amber và Rian nói về DNA", en:"Reading: Amber and Rian talk about DNA", blocks:[
      {kind:"passage", title:"👨‍👩‍👧 Bài đọc (Coursebook trang 82)", instr:"", text:"Amber and her brother Rian have both had a science lesson today, but they haven't learned exactly the same things. Amber has been learning about DNA, genetics and the human genome. She found out that about 99.9% of everyone's DNA is the same — it's a tiny part of our genes that makes us look different from each other, such as our hair and eye colour.\n\nRian, in a different class, has been learning about fingerprints. His class did an experiment comparing fingerprints and found that no two people — not even identical twins — have exactly the same pattern. That's why detectives use fingerprints found at a crime scene to help identify who was there: because every person's fingerprint is unique.\n\nAt dinner, Amber and Rian realise they've actually been learning about a similar topic — how science shows both what makes humans the same, and what makes each of us unique."},
      {kind:"mcq", title:"👨‍👩‍👧 Trả lời câu hỏi", instr:"", questions:[
        {q:"How much of everyone's DNA is the same?", opts:["About 99.9%","About 50%","About 10%"], a:0},
        {q:"What kind of differences do genes control, according to the text?", opts:["Things like hair and eye colour","A person's name","A person's favourite food"], a:0},
        {q:"Why is DNA/fingerprint evidence useful for solving crimes?", opts:["Because each person's DNA and fingerprints are unique","Because everyone has the same fingerprints","Because fingerprints change every day"], a:0},
        {q:"What did the fingerprint experiment show Rian's class?", opts:["No two people have exactly the same fingerprint pattern","Fingerprints are not useful for anything","Twins always have identical fingerprints"], a:0},
        {q:"What has Rian been learning about in science?", opts:["Fingerprints","Volcanoes","History"], a:0}
      ]}
    ]},
    {id:5, icon:"🔍", vn:"Tiếp diễn hay đã xong?", en:"Present perfect continuous or past simple?", blocks:[
      {kind:"classify", title:"🔍 Câu này nên dùng thì nào?", instr:"", cats:["Hiện tại hoàn thành tiếp diễn (tiếp diễn/vừa xảy ra)","Quá khứ đơn (đã xong, có thời điểm rõ ràng)"], items:[
        {word:"We've been learning about genetics all week.", ctx:"", cat:0},
        {word:"Yesterday, we did an experiment about fingerprints.", ctx:"", cat:1},
        {word:"Look, your hands are dirty — you've been gardening!", ctx:"", cat:0},
        {word:"Scientists discovered DNA structure in 1953.", ctx:"", cat:1},
        {word:"I've been reading about the human genome recently.", ctx:"", cat:0},
        {word:"She finished her science project last night.", ctx:"", cat:1}
      ]}
    ]},
    {id:6, icon:"✍️", vn:"Viết về những gì em đã học gần đây", en:"Write about what you've been doing/learning", blocks:[
      {kind:"writing", title:"✍️ Chuẩn bị bài nói ngắn (dùng have/has been + V-ing)", instr:"", tasks:[
        {prompt:"This week, we've been learning about ... (môn Khoa học)", sample:"This week, we've been learning about DNA, genes and genetics."},
        {prompt:"We've been finding out ...", sample:"We've been finding out how fingerprints can help solve crimes."},
        {prompt:"In another subject, I've been ...", sample:"In PE, we've been playing basketball and practising our shooting skills."}
      ]}
    ]},
    {id:7, icon:"🗣️", vn:"Luyện nói: DNA và sự khác biệt", en:"Speaking: DNA and what makes us different", blocks:[
      {kind:"speaking", title:"🗣️ Thẻ luyện nói", instr:"", cards:[
        {q:"Do any members of your family look alike? What features are similar?", vi:"Người thân trong gia đình em có nét giống nhau không? Đặc điểm nào giống?", sample:"My sister and I both have curly hair and brown eyes, just like our mum."},
        {q:"Why do you think DNA is important for solving crimes?", vi:"Vì sao DNA lại quan trọng trong việc phá án?", sample:"Because everyone's DNA is unique, so it can prove exactly who was at a crime scene."},
        {q:"What have you been learning about in science this week?", vi:"Tuần này em đã học gì trong môn Khoa học?", sample:"I've been learning about how plants grow."},
        {q:"What makes you unique compared to your friends?", vi:"Điều gì khiến em khác biệt (độc nhất) so với bạn bè?", sample:"I think my sense of humour and my love of drawing make me unique."}
      ]}
    ]},
    {id:8, icon:"👑", vn:"Trận Boss: Tổng ôn tập Unit 4.3", en:"Boss battle: Unit 4.3 review", blocks:[
      {kind:"boss", title:"👑 Trận Boss: Tổng ôn tập Unit 4.3", instr:"", items:[
        {kind:"mcq", q:"'unique' nghĩa là gì?", opts:["độc nhất, không cái nào giống","phổ biến","giống hệt"], a:0},
        {kind:"mcq", q:"'human genome' nghĩa là gì?", opts:["toàn bộ DNA của một người","1 gen duy nhất","dấu vân tay"], a:0},
        {kind:"gapfill", s:"We ___ about DNA and genetics all week. (have been learning)", a:"have been learning"},
        {kind:"gapfill", s:"Look at your hands — you ___ ! (have been painting)", a:"have been painting"},
        {kind:"classify", word:"Scientists discovered DNA structure in 1953.", ctx:"", cats:["Hiện tại hoàn thành tiếp diễn","Quá khứ đơn"], cat:1},
        {kind:"classify", word:"I've been reading about genetics recently.", ctx:"", cats:["Hiện tại hoàn thành tiếp diễn","Quá khứ đơn"], cat:0},
        {kind:"anagram", clue:"dấu vân tay", scrambled:"GRFTNIPESNRI", answer:"fingerprints"},
        {kind:"anagram", clue:"gen", scrambled:"EGEN", answer:"gene"},
        {kind:"mcq", q:"Khoảng bao nhiêu % DNA của mọi người là giống nhau?", opts:["99.9%","50%","10%"], a:0}
      ]}
    ]}
  ]
}});
CG9.addLesson({id:"u6-3", unit:6, type:"lesson", src:"Tho Gia Quy Quest - Cambridge Global English 9 Unit 6.3.html", game:{
  storageKey: "tho-quest-cge9-u63-v1",
  brand: "Thỏ Gia Quy Quest",
  subtitle: "Cambridge Global English 9 – Unit 6.3 House rules",
  mapTitle: "🏡 Bản đồ phiêu lưu: Nội quy trong nhà",
  mapIntro: "Cùng Thỏ khám phá từ vựng về nội quy trong nhà và học câu tường thuật (reported speech: câu hỏi, câu khẳng định, câu mệnh lệnh) — Unit 6.3, Cambridge Global English 9. Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ dựa theo Cambridge Global English Learner's Book 9 (2nd ed.), Unit 6 Rules and laws, bài 6.3 \"House rules\". Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Unit 6.3 – House rules",
  unlockAll: true,
  vocab: [
    {term:"a ban on (phones at the table)", vi:"lệnh cấm (điện thoại trên bàn ăn)", ex:"There's a ban on phones at the table in my house."},
    {term:"a phone-free zone", vi:"khu vực không dùng điện thoại", ex:"The dining room is a phone-free zone."},
    {term:"screen time", vi:"thời gian dùng màn hình", ex:"My screen time is limited to an hour a day."},
    {term:"make your bed", vi:"dọn giường", ex:"I have to make my bed every morning before school."},
    {term:"ask permission", vi:"xin phép", ex:"You have to ask permission before you go out with friends."}
  ],
  grammarNotes: [
    {title:"Câu hỏi tường thuật (Reported questions)", body:"Dùng if/whether để tường thuật câu hỏi Yes/No:\nAlisha: 'Can I stay up late?' → Alisha asked if/whether she could stay up late.\nVới câu hỏi có từ để hỏi (whose, what, where...), giữ nguyên trật tự câu khẳng định (KHÔNG đảo động từ):\nRaheem's dad: 'Whose house are you going to on Saturday?' → Raheem's dad asked Raheem whose house he was going to on Saturday. (KHÔNG nói 'whose house was he going to')"},
    {title:"Câu khẳng định & mệnh lệnh tường thuật (say/tell)", body:"say + (that) — không cần tân ngữ: Alisha: 'I want to watch the match.' → Alisha said she wanted to watch the match.\ntell + người nghe (him/her/tên...) — PHẢI có tân ngữ: Mum: 'You will have to do your homework first.' → Alisha's mum told her that she would have to do her homework first.\nMệnh lệnh: tell + người nghe + to + V: Mum: 'Clean the kitchen afterwards!' → Alisha's mum told her to clean the kitchen afterwards."}
  ],
  levels: [
    {id:1, icon:"🏡", vn:"Nối từ vựng nội quy trong nhà", en:"Match house rules vocabulary", blocks:[
      {kind:"match", title:"🏡 Nối từ với nghĩa tiếng Việt", instr:"Bấm 1 từ bên trái, rồi bấm nghĩa đúng bên phải.", pairs:[
        {left:"a ban on", right:"lệnh cấm"},
        {left:"a phone-free zone", right:"khu vực không dùng điện thoại"},
        {left:"screen time", right:"thời gian dùng màn hình"},
        {left:"make your bed", right:"dọn giường"},
        {left:"ask permission", right:"xin phép"}
      ]}
    ]},
    {id:2, icon:"❓", vn:"Trắc nghiệm từ vựng nội quy trong nhà", en:"Multiple choice: house rules vocabulary", blocks:[
      {kind:"mcq", title:"❓ Chọn đáp án đúng", instr:"", questions:[
        {q:"A rule that stops you doing something is called...", opts:["a ban","a permission","a schedule"], a:0},
        {q:"A place where phones are not allowed is called...", opts:["a phone-free zone","a detention","a workload"], a:0},
        {q:"The amount of time you spend looking at a phone, TV or computer is your...", opts:["screen time","workload","schedule"], a:0},
        {q:"If you tidy your bedroom's bed in the morning, you...", opts:["make your bed","break the rules","ask permission"], a:0},
        {q:"If you want to do something and you ask an adult if it's OK, you...", opts:["ask permission","make your bed","get a detention"], a:0}
      ]}
    ]},
    {id:3, icon:"⚙️", vn:"Ngữ pháp: câu hỏi tường thuật", en:"Grammar: reported questions", blocks:[
      {kind:"theory", title:"⚙️ if/whether & trật tự từ", instr:"", html:"<b>Câu hỏi Yes/No</b> → dùng if/whether:<br>Alisha: 'Can I stay up late?' → Alisha asked <b>if/whether</b> she <b>could</b> stay up late.<br><b>Câu hỏi có từ để hỏi</b> (whose, what, where...) → giữ trật tự câu khẳng định:<br>Dad: 'Whose house are you going to?' → Dad asked Raheem <b>whose house he was</b> going to. <i>(KHÔNG đảo động từ lên trước chủ ngữ)</i>"},
      {kind:"gapfill", title:"⚙️ Viết lại câu hỏi thành câu tường thuật", instr:"", items:[
        {pre:"Alisha: 'Can I make a pizza?' → Alisha asked", post:"she could make a pizza.", answers:["if","whether"]},
        {pre:"Raheem: 'Are we doing anything on Saturday?' → Raheem asked", post:"they were doing anything on Saturday.", answers:["if","whether"]},
        {pre:"Dad: 'What time are you going?' → Dad asked him what time", post:"going. (giữ trật tự câu khẳng định)", answers:["he was"]},
        {pre:"Raheem: 'Can I take the new balls to play with?' → Raheem asked", post:"he could take the new balls to play with.", answers:["if","whether"]}
      ]}
    ]},
    {id:4, icon:"🎧", vn:"Nghe: Alisha & Raheem so sánh nội quy", en:"Listening: Alisha and Raheem comparing rules", blocks:[
      {kind:"passage", title:"🎧 Tóm tắt bài nghe", instr:"", text:"Alisha and Raheem are comparing their families' rules. Alisha's family has a ban on phones at the table, and the dining room is a phone-free zone. She has to ask permission before going out with friends, and her screen time is limited on school nights. Raheem has to make his bed every morning, and there are rules about doors, lights and computers being switched off. Both of them have to ask permission for three things: going out, buying things online, and staying up late. Alisha and Raheem agree that having rules at home helps keep things calm and fair, even though they sometimes find the rules annoying."},
      {kind:"classify", title:"🎧 Nội quy này là về ĐIỆN THOẠI/MÀN HÌNH hay VIỆC NHÀ?", instr:"", cats:["Điện thoại / màn hình","Việc nhà"], items:[
        {word:"There's a ban on phones at the table.", ctx:"", cat:0},
        {word:"Make your bed every morning.", ctx:"", cat:1},
        {word:"The dining room is a phone-free zone.", ctx:"", cat:0},
        {word:"Screen time is limited on school nights.", ctx:"", cat:0}
      ]}
    ]},
    {id:5, icon:"💬", vn:"Câu khẳng định & mệnh lệnh tường thuật", en:"Reported statements and commands", blocks:[
      {kind:"theory", title:"💬 say / tell / mệnh lệnh", instr:"", html:"<b>say</b> (không cần tân ngữ): Alisha: 'I want to watch the match.' → Alisha <b>said</b> she wanted to watch the match.<br><b>tell + tân ngữ</b> (PHẢI có người nghe): Mum: 'You will have to do your homework first.' → Alisha's mum <b>told her</b> that she would have to do her homework first.<br><b>Mệnh lệnh: tell + tân ngữ + to + V</b>: Mum: 'Clean the kitchen!' → Mum <b>told her to clean</b> the kitchen."},
      {kind:"gapfill", title:"💬 Điền said/told đúng", instr:"", items:[
        {pre:"Raheem to his dad: 'We're going to play table tennis.' → Raheem", post:"they were going to play table tennis.", answers:["said"]},
        {pre:"Raheem's dad to Raheem: 'Bring them back.' → Raheem's dad", post:"him to bring them back.", answers:["told"]},
        {pre:"Alisha: 'I want to watch the football match.' → Alisha", post:"she wanted to watch the football match.", answers:["said"]},
        {pre:"Mum to Alisha: 'You will have to do your homework first.' → Alisha's mum", post:"her that she would have to do her homework first.", answers:["told"]}
      ]}
    ]},
    {id:6, icon:"✍️", vn:"Viết về nội quy trong nhà em", en:"Writing about rules at your home", blocks:[
      {kind:"writing", title:"✍️ Viết câu của riêng em", instr:"", tasks:[
        {prompt:"Viết 1 câu dùng từ vựng bài học (ban on/phone-free zone/screen time/ask permission) nói về nội quy nhà em.", sample:"In my house, my screen time is limited to two hours a day, and I always have to ask permission before I go out."},
        {prompt:"Viết lại câu hỏi sau thành câu tường thuật: Mum asked, 'Can you make your bed before school?'", sample:"Mum asked if/whether I could make my bed before school."},
        {prompt:"Viết 1 câu mệnh lệnh tường thuật (tell + to + V) mà bố/mẹ em từng nói với em.", sample:"My dad told me to turn off the lights before I left my room."}
      ]}
    ]},
    {id:7, icon:"🗣️", vn:"Luyện nói: So sánh nội quy gia đình", en:"Speaking: comparing family rules", blocks:[
      {kind:"speaking", title:"🗣️ Thẻ luyện nói", instr:"", cards:[
        {q:"Do families need rules? Why? What kind of things do you have rules about at home?", vi:"Gia đình có cần nội quy không? Vì sao? Nhà em có nội quy về những gì?", sample:"Yes, I think families need rules, because they help everyone know what's expected. At home, we have rules about screen time and phones at the table."},
        {q:"Do you have rules about phones at home?", vi:"Nhà em có nội quy về điện thoại không?", sample:"Yes, we aren't allowed to use our phones during meals, so the dining room is a phone-free zone."},
        {q:"What are the rules about homework at your house?", vi:"Nội quy về bài tập về nhà ở nhà em thế nào?", sample:"We're expected to finish our homework before we're allowed any screen time."},
        {q:"What three things do you have to ask permission for at home?", vi:"Có ba việc gì em phải xin phép ở nhà?", sample:"I have to ask permission to go out with friends, to buy things online, and to stay up late."}
      ]}
    ]},
    {id:8, icon:"👑", vn:"Trận Boss: Tổng ôn tập Unit 6.3", en:"Boss battle: Unit 6.3 review", blocks:[
      {kind:"boss", title:"👑 Trận Boss: Tổng ôn tập Unit 6.3", instr:"", items:[
        {kind:"mcq", q:"'screen time' nghĩa là gì?", opts:["thời gian dùng màn hình","lệnh cấm","xin phép"], a:0},
        {kind:"mcq", q:"'ask permission' nghĩa là gì?", opts:["xin phép","dọn giường","bị cấm"], a:0},
        {kind:"gapfill", s:"Alisha: 'Can I stay up late?' → Alisha asked ___ she could stay up late.", a:"if"},
        {kind:"classify", word:"Make your bed every morning.", ctx:"", cats:["Điện thoại / màn hình","Việc nhà"], cat:1},
        {kind:"classify", word:"There's a ban on phones at the table.", ctx:"", cats:["Điện thoại / màn hình","Việc nhà"], cat:0},
        {kind:"mcq", q:"Raheem's dad to Raheem: 'Bring them back.' → Raheem's dad ___ him to bring them back.", opts:["told","said","asked"], a:0},
        {kind:"anagram", clue:"xin phép (động từ)", scrambled:"KSA NOISPERISM", answer:"ask permission"},
        {kind:"gapfill", s:"Dad asked Raheem whose house he ___ going to on Saturday. (giữ trật tự câu khẳng định)", a:"was"}
      ]}
    ]}
  ]
}});
CG9.addLesson({id:"u2-6", unit:2, type:"lesson", src:"Tho Happy Quest - Cambridge Global English 9 Unit 2.6.html", game:{
  storageKey: "tho-quest-cge9-u26-v1",
  brand: "Thỏ Happy Quest",
  subtitle: "Cambridge Global English 9 – Unit 2.6 How to be happy",
  mapTitle: "😊 Bản đồ phiêu lưu: Bí quyết hạnh phúc",
  mapIntro: "Cùng Thỏ học từ vựng và cách diễn đạt quan điểm về hạnh phúc — Unit 2.6, Cambridge Global English 9. Không tính giờ, sai bao nhiêu lần cũng được!",
  footer: "Tự soạn cho bé Thỏ dựa theo Cambridge Global English Learner's Book 9 &amp; Workbook 9 (2nd ed.), Unit 2.6 \"How to be happy\". Tiến độ lưu trên trình duyệt này.",
  notebookTitle: "📖 Sổ tay Unit 2.6 – How to be happy",
  vocab: [
    {term:"a supportive family", vi:"một gia đình luôn ủng hộ, hỗ trợ", ex:"I'm lucky because I've got a really supportive family."},
    {term:"get involved in", vi:"tham gia vào", ex:"They encourage me to get involved in activities like sports and drama."},
    {term:"get anxious", vi:"trở nên lo lắng", ex:"I can get quite anxious sometimes."},
    {term:"get on with", vi:"hòa hợp với, sống hòa thuận với", ex:"I like being at home, just getting on with things I'm interested in."},
    {term:"get angry / behave badly", vi:"trở nên tức giận / cư xử tệ", ex:"I feel uncomfortable with situations when people get angry or behave badly."},
    {term:"bullying", vi:"bắt nạt", ex:"Bullying can make people feel very unhappy."},
    {term:"friendship", vi:"tình bạn", ex:"Friends make you laugh when you feel a bit down."},
    {term:"physical and mental well-being", vi:"sức khỏe thể chất và tinh thần", ex:"Being happy is a combination of feeling well physically and mentally."},
    {term:"stress and anxiety", vi:"căng thẳng và lo âu", ex:"Regular exercise can help combat stress and anxiety."},
    {term:"talking in front of other people", vi:"nói chuyện trước đám đông", ex:"I feel a bit nervous about talking in front of other people."},
    {term:"a bit down", vi:"hơi buồn", ex:"Friends make you laugh when you feel a bit down."},
    {term:"combat", vi:"chống lại, đối phó với", ex:"Eating a balanced diet is a good way to combat stress."}
  ],
  grammarNotes: [
    {title:"Dùng 'get' + tính từ", body:"Động từ 'get' rất hay được dùng trong văn nói/viết thân mật để nói về sự thay đổi trạng thái: get anxious (trở nên lo lắng), get angry (trở nên tức giận), get involved in (tham gia vào), get on with (hòa hợp với / tiếp tục làm gì đó). Dùng 'really, quite, a bit' để nhấn mạnh mức độ: 'I get quite anxious.', 'I get a bit nervous.'"}
  ],
  levels: [
    {id:1, icon:"😊", vn:"Nối từ vựng về hạnh phúc", en:"Match happiness vocabulary", blocks:[
      {kind:"match", title:"😊 Nối từ/cụm từ với nghĩa tiếng Việt", instr:"Bấm 1 từ bên trái, rồi bấm nghĩa đúng bên phải.", pairs:[
        {left:"a supportive family", right:"một gia đình luôn ủng hộ, hỗ trợ"},
        {left:"get involved in", right:"tham gia vào"},
        {left:"get anxious", right:"trở nên lo lắng"},
        {left:"get on with", right:"hòa hợp với"},
        {left:"behave badly", right:"cư xử tệ"},
        {left:"bullying", right:"bắt nạt"},
        {left:"friendship", right:"tình bạn"},
        {left:"physical and mental well-being", right:"sức khỏe thể chất và tinh thần"},
        {left:"stress and anxiety", right:"căng thẳng và lo âu"},
        {left:"talking in front of other people", right:"nói chuyện trước đám đông"},
        {left:"a bit down", right:"hơi buồn"},
        {left:"combat", right:"chống lại, đối phó với"}
      ]}
    ]},
    {id:2, icon:"❓", vn:"Trắc nghiệm từ vựng", en:"Vocabulary multiple choice", blocks:[
      {kind:"mcq", title:"❓ Chọn từ đúng nhất", instr:"", questions:[
        {q:"I've got a really ______ family — they always help me.", opts:["supportive","anxious","badly behaved"], a:0},
        {q:"My parents encourage me to ______ activities like sports and drama.", opts:["get involved in","get angry about","get anxious about"], a:0},
        {q:"I like being at home, just ______ things I'm interested in.", opts:["getting on with","getting involved with","getting angry with"], a:0},
        {q:"I feel uncomfortable when people ______ or behave badly.", opts:["get angry","get involved","get on"], a:0},
        {q:"Regular exercise is a good way to ______ stress and anxiety.", opts:["combat","bully","support"], a:0},
        {q:"A good ______ can make you laugh when you feel a bit down.", opts:["friendship","bullying","anxiety"], a:0},
        {q:"Being happy is a combination of physical and mental ______.", opts:["well-being","bullying","annoyance"], a:0},
        {q:"I get quite ______ about talking in front of other people.", opts:["nervous","supportive","involved"], a:0}
      ]}
    ]},
    {id:3, icon:"📻", vn:"Podcast: How to be happy", en:"Podcast opinions about happiness", blocks:[
      {kind:"passage", title:"📻 Các ý kiến từ podcast (Coursebook trang 44)", instr:"", text:"a) \"I don't think you can expect to feel really happy all the time. Sometimes you just feel OK, and that's fine.\"\n\nb) \"Friends make you laugh when you feel a bit down. They support you when you're worried or when you don't feel confident.\"\n\nc) \"I feel uncomfortable with situations when people get angry or behave badly and disrupt lessons at school.\"\n\nd) \"It's fun to be with other people and do things you enjoy.\"\n\ne) \"I find that just sharing the problem with a friend helps me feel much happier.\"\n\nf) \"I think being happy is a combination of lots of things: feeling well physically and also mentally, so that you feel you can do your best and enjoy life.\""},
      {kind:"mcq", title:"❓ Ý kiến nào nói về...?", instr:"Đọc lại các ý kiến a-f ở trên và chọn đáp án đúng.", questions:[
        {q:"Ý kiến nào nói rằng bạn bè giúp ta vui hơn khi buồn?", opts:["b","c","d"], a:0},
        {q:"Ý kiến nào nói rằng không cần lúc nào cũng phải thật vui, chỉ cần 'ổn' cũng được?", opts:["a","e","f"], a:0},
        {q:"Ý kiến nào nói rằng hạnh phúc là sự kết hợp giữa sức khỏe thể chất và tinh thần?", opts:["f","c","d"], a:0},
        {q:"Ý kiến nào nói về việc chia sẻ vấn đề với bạn bè giúp cảm thấy vui hơn?", opts:["e","a","d"], a:0},
        {q:"Ý kiến nào nói về việc cảm thấy khó chịu khi người khác cư xử tệ ở trường?", opts:["c","b","f"], a:0}
      ]}
    ]},
    {id:4, icon:"📝", vn:"Blog của Emine: Sắp xếp câu", en:"Emine's blog: where do sentences go?", blocks:[
      {kind:"passage", title:"📝 Blog về hạnh phúc (Workbook trang 33)", instr:"", text:"My podcast today is about how to be happy. What are some active strategies for maintaining a positive mindset? I'm going to suggest three ways we can help ourselves to be happy.\n\n[1] First, it's really obvious, but also very true that our health influences our mood. Getting enough sleep, doing regular exercise and eating a balanced diet are all good ways to combat stress and anxiety. [A]\n\n[2] Second, it's good to vary our activities every day. Socialising and getting involved in activities with others is really important. But having time on our own to reflect on things is necessary too. Sometimes we need to concentrate hard on tasks that are quite difficult and other times we need to relax more. [B]\n\n[3] Finally, try to focus on the good things in your daily life. Whether you're with your family or at school, look around you and say what you are grateful for. It can be something small, like a sunny day or getting good marks on a quiz. [C]\n\nWell, that's all from me today. What do you think about how to be happy? Leave a comment!"},
      {kind:"match", title:"📝 Câu này nên chèn vào vị trí nào?", instr:"Nối mỗi câu với vị trí [A], [B] hoặc [C] hợp lý nhất trong bài blog.", pairs:[
        {left:"If our brains and bodies are rested and well-nourished, we will feel good.", right:"[A]"},
        {left:"So a balance of activities throughout the day is super important.", right:"[B]"},
        {left:"Try doing this at least once a day – it can really lift your mood.", right:"[C]"}
      ]},
      {kind:"writing", title:"✍️ Tóm tắt blog trong 1 câu", instr:"", tasks:[
        {prompt:"Viết 1 câu tóm tắt ý chính của blog Emine.", sample:"Emine suggests three ways to be happy: taking care of your health, balancing your activities, and focusing on the good things in life."}
      ]}
    ]},
    {id:5, icon:"🔤", vn:"Hoàn thành câu với 'get'", en:"Gap-fill with get + adjective", blocks:[
      {kind:"gapfill", title:"🔤 Điền từ đúng vào chỗ trống", instr:"Dùng các từ trong ngân hàng từ để hoàn thành câu.", wordbank:["anxious","involved in","on with","angry","supportive","down"], items:[
        {pre:"I always get a bit", post:"before a speaking test.", answers:["anxious"]},
        {pre:"My school encourages students to get", post:"clubs and activities.", answers:["involved in"]},
        {pre:"I like being at home, just getting", post:"my hobbies.", answers:["on with"]},
        {pre:"He gets really", post:"when his little sister touches his things.", answers:["angry"]},
        {pre:"I'm lucky to have a really", post:"family who helps me with everything.", answers:["supportive"]},
        {pre:"Sometimes I feel a bit", post:"when it rains all week.", answers:["down"]}
      ]}
    ]},
    {id:6, icon:"✍️", vn:"Viết email trả lời podcast", en:"Write an email reply", blocks:[
      {kind:"theory", title:"✍️ Cấu trúc email trả lời", instr:"", html:"Dùng các cụm nối câu: <i>I feel really happy when I ... / I think ... also helps me to be happy because ... / I sometimes feel a bit ... when ... but to deal with situations like that, I just ... / Overall, I would say that the most important aspect is ...</i>"},
      {kind:"writing", title:"✍️ Viết email nêu quan điểm về hạnh phúc", instr:"Dùng khung câu ở trên để viết 3-4 câu.", tasks:[
        {prompt:"What makes you feel really happy?", sample:"I feel really happy when I spend time with my family at the weekend."},
        {prompt:"What makes you feel unhappy, worried or a bit down, and how do you deal with it?", sample:"I sometimes feel a bit anxious before exams, but to deal with that, I just make a study plan and take breaks."},
        {prompt:"Overall, what would you say is the most important aspect of being happy?", sample:"Overall, I would say that the most important aspect is having a supportive family and good friends."}
      ]}
    ]},
    {id:7, icon:"🗣️", vn:"Luyện nói: Điều gì khiến em hạnh phúc?", en:"Speaking: what makes you happy?", blocks:[
      {kind:"speaking", title:"🗣️ Thẻ luyện nói", instr:"Đọc câu hỏi, nói to câu trả lời, rồi bấm vào thẻ để xem gợi ý.", cards:[
        {q:"What makes you feel really happy?", vi:"Điều gì khiến em cảm thấy thực sự hạnh phúc?", sample:"Spending time with my friends makes me feel really happy."},
        {q:"What makes you feel unhappy, uncomfortable, worried, depressed or just a bit down?", vi:"Điều gì khiến em cảm thấy không vui, khó chịu, lo lắng hoặc hơi buồn?", sample:"I feel a bit down when I don't do well on a test."},
        {q:"How do you deal with difficult situations that make you feel unhappy?", vi:"Em xử lý thế nào khi gặp tình huống khó khăn khiến mình không vui?", sample:"I talk to my parents or listen to music to feel better."},
        {q:"Overall, what would you say is the most important aspect of being happy?", vi:"Nhìn chung, điều gì em cho là quan trọng nhất để hạnh phúc?", sample:"I think having a supportive family is the most important thing."}
      ]}
    ]},
    {id:8, icon:"👑", vn:"Trận Boss: Tổng ôn tập Unit 2.6", en:"Boss battle: Unit 2.6 review", blocks:[
      {kind:"boss", title:"👑 Trận Boss: Tổng ôn tập Unit 2.6", instr:"Trộn tất cả các dạng bài đã học!", items:[
        {kind:"mcq", q:"'a supportive family' nghĩa là gì?", opts:["một gia đình luôn ủng hộ, hỗ trợ","một gia đình nghiêm khắc","một gia đình đông người"], a:0},
        {kind:"gapfill", s:"My school encourages me to get ___ activities like drama and sports.", a:"involved in"},
        {kind:"gapfill", s:"I get quite ___ about talking in front of other people.", a:"nervous"},
        {kind:"choice2", s:"Regular exercise is a good way to ___ stress.", options:["combat","bully"], a:"combat"},
        {kind:"mcq", q:"Theo blog của Emine, điều gì giúp ta hạnh phúc?", opts:["Ngủ đủ, cân bằng hoạt động, và biết ơn điều tốt đẹp","Chỉ cần học thật giỏi","Không cần làm gì cả"], a:0},
        {kind:"anagram", clue:"tình bạn", scrambled:"PDIRFHINES", answer:"friendship"},
        {kind:"anagram", clue:"bắt nạt", scrambled:"YULBGNIL", answer:"bullying"},
        {kind:"transform", s:"He behaves badly and gets ______ easily. (angry)", root:"GET", a:"angry"},
        {kind:"mcq", q:"'I like being at home, just getting on with things I'm interested in' nghĩa là gì?", opts:["Thích ở nhà làm việc mình thích","Thích đi chơi với bạn bè","Thích tranh cãi với gia đình"], a:0},
        {kind:"gapfill", s:"Being happy is a combination of physical and mental ___.", a:"well-being"}
      ]}
    ]}
  ]
}});
CG9.addLesson({id:"u6-2", unit:6, type:"lesson", src:"Tho Kaizen Quest - Cambridge Global English 9 Unit 6.2.html", game:{
  storageKey: "tho-quest-cge9-u62-v1",
  brand: "Thỏ Kaizen Quest",
  subtitle: "Cambridge Global English 9 – Unit 6.2 Family life",
  mapTitle: "🏠 Bản đồ phiêu lưu: Kaizen trong gia đình",
  mapIntro: "Cùng Thỏ đọc bài báo về gia đình Thuỵ Điển áp dụng phương pháp Kaizen vào việc nhà, học từ vựng quản trị kinh doanh và thể bị động với động từ nguyên mẫu (to be + P.P.) — Unit 6.2, Cambridge Global English 9. Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ dựa theo Cambridge Global English Learner's Book 9 (2nd ed.), Unit 6 Rules and laws, bài 6.2 \"Family life\". Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Unit 6.2 – Family life",
  unlockAll: true,
  vocab: [
    {term:"efficiency", vi:"hiệu quả, hiệu suất", ex:"Kaizen produced big improvements in productivity and efficiency."},
    {term:"employee", vi:"nhân viên", ex:"The idea is to involve all employees in continuously improving work processes."},
    {term:"executive", vi:"giám đốc điều hành, quản lý cấp cao", ex:"Eva worked as an executive for a pharmaceutical company."},
    {term:"management practice", vi:"phương pháp/thông lệ quản lý", ex:"Kaizen became part of management practices internationally."},
    {term:"process", vi:"quy trình", ex:"The idea is to continuously improve all work processes."},
    {term:"productivity", vi:"năng suất", ex:"Kaizen produced big improvements in productivity and efficiency."},
    {term:"schedule", vi:"lịch trình, kế hoạch", ex:"The plan is a two-week schedule that includes everything they will be doing."},
    {term:"set goals", vi:"đặt mục tiêu", ex:"They also set goals and decide how to resolve any problems as they arise."},
    {term:"system", vi:"hệ thống", ex:"Mattias had witnessed how the system made things run more smoothly in hospitals."},
    {term:"workload", vi:"khối lượng công việc", ex:"There's no resentment over unfinished chores or unfair workloads."}
  ],
  grammarNotes: [
    {title:"Thể bị động với động từ nguyên mẫu (to be + P.P.)", body:"Dùng 'to be + quá khứ phân từ' để nói về việc gì đó cần được làm.\nThe house was in chaos, with piles of washing to be done and clothes to be ironed.\nThere's a lot of housework to be finished before the weekend."},
    {title:"Kaizen là gì?", body:"Kaizen là từ tiếng Nhật nghĩa là 'sự cải tiến' (improvement). Đây là một quy trình trong kinh doanh, sau đó trở thành một phương pháp quản lý phổ biến trên toàn thế giới. Mục tiêu: liên tục cải tiến các quy trình làm việc, giảm lãng phí (waste), và để tất cả nhân viên (employees) cùng tham gia."}
  ],
  levels: [
    {id:1, icon:"🏠", vn:"Nối từ vựng quản trị kinh doanh", en:"Match business vocabulary", blocks:[
      {kind:"match", title:"🏠 Nối từ với nghĩa tiếng Việt", instr:"Bấm 1 từ bên trái, rồi bấm nghĩa đúng bên phải.", pairs:[
        {left:"efficiency", right:"hiệu quả, hiệu suất"},
        {left:"employee", right:"nhân viên"},
        {left:"executive", right:"giám đốc điều hành"},
        {left:"management practice", right:"phương pháp quản lý"},
        {left:"process", right:"quy trình"},
        {left:"productivity", right:"năng suất"},
        {left:"schedule", right:"lịch trình"},
        {left:"set goals", right:"đặt mục tiêu"},
        {left:"system", right:"hệ thống"},
        {left:"workload", right:"khối lượng công việc"}
      ]}
    ]},
    {id:2, icon:"❓", vn:"Trắc nghiệm từ vựng quản trị kinh doanh", en:"Multiple choice: business vocabulary", blocks:[
      {kind:"mcq", title:"❓ Chọn đáp án đúng", instr:"", questions:[
        {q:"A senior manager who runs a business is a/an...", opts:["executive","employee","system"], a:0},
        {q:"The amount of work someone has to do is their...", opts:["workload","efficiency","schedule"], a:0},
        {q:"A plan of when things will happen is a...", opts:["schedule","process","employee"], a:0},
        {q:"How much is produced in a certain amount of time is...", opts:["productivity","efficiency","workload"], a:0},
        {q:"How well something works, without wasting time or resources, is...", opts:["efficiency","productivity","workload"], a:0},
        {q:"A series of actions taken to achieve something is a...", opts:["process","schedule","executive"], a:0},
        {q:"A person who works for a company is a/an...", opts:["employee","executive","system"], a:0}
      ]}
    ]},
    {id:3, icon:"⚙️", vn:"Ngữ pháp: thể bị động + động từ nguyên mẫu", en:"Grammar: passive infinitive", blocks:[
      {kind:"theory", title:"⚙️ to be + quá khứ phân từ (P.P.)", instr:"", html:"Dùng <b>to be + P.P.</b> để nói về việc gì đó cần được làm (thường sau danh từ):<br>The house was in chaos, with piles of washing <b>to be done</b> and clothes <b>to be ironed</b>.<br>There's a lot of homework <b>to be finished</b> tonight."},
      {kind:"gapfill", title:"⚙️ Điền dạng bị động nguyên mẫu (to be + P.P.)", instr:"", items:[
        {pre:"There were a lot of dishes", post:"(wash) after the party.", answers:["to be washed"]},
        {pre:"There's a report", post:"(finish) before Friday.", answers:["to be finished"]},
        {pre:"There was a room", post:"(clean) before the guests arrived.", answers:["to be cleaned"]},
        {pre:"There are three emails", post:"(send) before lunch.", answers:["to be sent"]}
      ]}
    ]},
    {id:4, icon:"📰", vn:"Đọc hiểu: Run your home like a business", en:"Reading: Run your home like a business", blocks:[
      {kind:"passage", title:"📰 Run your home like a business. This was the solution for a busy Swedish family.", instr:"", text:"Eva Jarlsdotter and her husband Mattias have three children. They live in Stockholm. Eva is a writer and businesswoman and Mattias is a doctor. At home, their life had become hectic, allowing little time for household chores. The house was in chaos, with piles of washing to be done and clothes to be ironed. Everyone was feeling stressed. They knew that something needed to change.\n\nThe family started to use a business strategy to sort out their chaotic homelife. Eva had seen how kaizen (the 'lean' method) produced big improvements in productivity and efficiency while working as an executive for a pharmaceutical company. Mattias had also witnessed how the system made things run more smoothly in hospitals.\n\nKaizen is a Japanese word for 'improvement'. It was first used as a process in business in Japan and then became part of management practices internationally. Kaizen was named the 'lean' method because it aimed to avoid waste and make work run smoothly by removing any problems. The idea is to continuously improve all work processes and to involve all employees in doing so.\n\nEva says that the family applied kaizen by first thinking about the process of running their home as a thread and tried to identify all the 'knots', the problems that were slowing things down.\n\nFirst, they sorted their dirty clothes into four bags: one each for delicate fabrics, colours, white and black clothes. Every member of the family was expected to put their clothes in the correct bags, even Samuel, who was only two years old at the time.\n\nAccording to the new house rules, when a laundry bag was full, whoever had filled it had to load it into the washing machine. Then they dried and ironed the clothes as soon as the load was finished.\n\nThe household chores are shared. Eva says, 'Our children – Vendela, now 16, Tuva, 14 and Samuel, ten – pitch in with everything from loading the dishwasher to doing the laundry. And there's no resentment over unfinished chores or unfair workloads.'\n\nThe family also decided that they needed a shared plan that was clear to everyone, so they wrote one and put it on their noticeboard. The plan is a two-week schedule that includes everything that they will be doing. On Sunday evenings, they have a 15-minute family meeting to discuss what is happening in the coming fortnight. They also set goals and decide how to resolve any problems as they arise.\n\nAccording to Eva, by applying the 'lean' approach and making a few simple changes to their routines, they have made their home life happier and much more relaxed."},
      {kind:"mcq", title:"📰 Câu hỏi đọc hiểu", instr:"", questions:[
        {q:"Why did the Swedish family decide they needed to make changes?", opts:["Their home life had become hectic and stressful","They wanted to move house","Mattias lost his job"], a:0},
        {q:"Where did Eva first see the kaizen method being used?", opts:["Working as an executive for a pharmaceutical company","At university","On television"], a:0},
        {q:"How many bags did they sort dirty clothes into?", opts:["Four","Two","Six"], a:0},
        {q:"How often do they have a family meeting?", opts:["Every Sunday evening","Every morning","Once a month"], a:0}
      ]}
    ]},
    {id:5, icon:"🧵", vn:"Kaizen: quy trình & lợi ích", en:"Kaizen: process and benefits", blocks:[
      {kind:"theory", title:"🧵 Kaizen hoạt động thế nào?", instr:"", html:"1) Nghĩ về quy trình (<b>process</b>) như một sợi chỉ, tìm ra các 'nút thắt' (knots) — vấn đề làm chậm mọi thứ.<br>2) Đặt ra quy tắc rõ ràng cho mọi người (ví dụ: phân loại quần áo bẩn vào 4 túi).<br>3) Viết kế hoạch/lịch trình (<b>schedule</b>) chung, họp gia đình định kỳ.<br>4) Đặt mục tiêu (<b>set goals</b>) và giải quyết vấn đề khi phát sinh."},
      {kind:"classify", title:"🧵 Đây là một BƯỚC trong quy trình Kaizen của gia đình Eva hay một LỢI ÍCH đạt được?", instr:"", cats:["Bước trong quy trình","Lợi ích đạt được"], items:[
        {word:"Sort dirty clothes into four bags.", ctx:"", cat:0},
        {word:"Their home life became happier and more relaxed.", ctx:"", cat:1},
        {word:"Have a 15-minute family meeting every Sunday evening.", ctx:"", cat:0},
        {word:"There's no resentment over unfair workloads.", ctx:"", cat:1}
      ]}
    ]},
    {id:6, icon:"✍️", vn:"Viết về việc nhà trong gia đình em", en:"Writing about chores in your family", blocks:[
      {kind:"writing", title:"✍️ Viết câu của riêng em", instr:"", tasks:[
        {prompt:"Viết 1 câu dùng 'to be + P.P.' nói về việc nhà cần làm ở nhà em.", sample:"There are always dishes to be washed after dinner at my house."},
        {prompt:"Viết 2-3 câu đề xuất một 'management practice' (như kaizen) mà gia đình em có thể áp dụng để chia việc nhà công bằng hơn.", sample:"I think my family could make a weekly schedule for chores, like Eva's family did. We could set goals together and have a short family meeting every week to check the schedule."}
      ]}
    ]},
    {id:7, icon:"🗣️", vn:"Luyện nói: Việc nhà & Kaizen", en:"Speaking: chores and Kaizen", blocks:[
      {kind:"speaking", title:"🗣️ Thẻ luyện nói", instr:"", cards:[
        {q:"Why do you think this method (kaizen) is used to improve productivity and efficiency?", vi:"Vì sao phương pháp này (kaizen) được dùng để cải thiện năng suất và hiệu quả?", sample:"I think it works because it focuses on finding and removing small problems continuously, instead of trying to fix everything at once."},
        {q:"Does it need to be a continuous process? Why?", vi:"Đây có cần là một quy trình liên tục không? Vì sao?", sample:"Yes, because new problems always appear, so you need to keep checking and improving."},
        {q:"Is the process something that only managers and executives do, or does it involve other workers?", vi:"Quy trình này chỉ dành cho quản lý hay có sự tham gia của tất cả nhân viên?", sample:"It involves everyone, even Samuel who was only two years old, which shows that everyone's opinion matters."},
        {q:"What are the best things about family life?", vi:"Những điều tốt đẹp nhất về đời sống gia đình là gì?", sample:"I think spending time together and supporting each other are the best things about family life."}
      ]}
    ]},
    {id:8, icon:"👑", vn:"Trận Boss: Tổng ôn tập Unit 6.2", en:"Boss battle: Unit 6.2 review", blocks:[
      {kind:"boss", title:"👑 Trận Boss: Tổng ôn tập Unit 6.2", instr:"", items:[
        {kind:"mcq", q:"'workload' nghĩa là gì?", opts:["khối lượng công việc","hiệu quả","nhân viên"], a:0},
        {kind:"mcq", q:"'kaizen' là từ tiếng gì và nghĩa là gì?", opts:["tiếng Nhật, nghĩa là 'sự cải tiến'","tiếng Anh, nghĩa là 'công việc'","tiếng Pháp, nghĩa là 'gia đình'"], a:0},
        {kind:"gapfill", s:"There were piles of washing ___ ___ (do) and clothes to be ironed.", a:"to be done"},
        {kind:"classify", word:"Have a 15-minute family meeting every Sunday evening.", ctx:"", cats:["Bước trong quy trình","Lợi ích đạt được"], cat:0},
        {kind:"classify", word:"Their home life became happier and more relaxed.", ctx:"", cats:["Bước trong quy trình","Lợi ích đạt được"], cat:1},
        {kind:"mcq", q:"Eva worked as an executive for what kind of company before applying kaizen at home?", opts:["A pharmaceutical company","A food company","A car company"], a:0},
        {kind:"anagram", clue:"năng suất", scrambled:"TYVIIDCUPROT", answer:"productivity"},
        {kind:"gapfill", s:"There's a report ___ ___ (finish) before Friday.", a:"to be finished"}
      ]}
    ]}
  ]
}});
CG9.addLesson({id:"u1-connect", unit:1, type:"connect", src:"Tho Ket Noi Quest - Cambridge Global English 9 Unit 1.html", game:{
  storageKey: "tho-mixed-cge9-u1-v1",
  brand: "Thỏ Kết Nối Quest",
  subtitle: "Cambridge Global English 9 – Unit 1 Kết nối & Nâng cao",
  mapTitle: "🔗 Bản đồ phiêu lưu: Kết nối toàn Unit 1",
  mapIntro: "Cùng Thỏ nối các mảnh ghép từ vựng và ngữ pháp của cả 8 bài trong Unit 1 (Views and voices), ôn tổng hợp ngữ pháp, thử sức dịch một đoạn báo thật, và chinh phục trận Boss nâng cao cuối cùng! Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ dựa theo Cambridge Global English Learner's Book 9 (2nd ed.), Unit 1 Views and voices (bài 1.1–1.8). Đoạn dịch ở màn 6 trích từ báo Giáo dục & Thời đại (giaoducthoidai.vn), bài \"Kỹ năng rèn luyện giúp con tự tin\". Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Kết Nối – Unit 1 (từ vựng chọn lọc)",
  unlockAll: true,
  vocab: [
    {term:"distract", vi:"làm xao nhãng", ex:"Loud music can distract you from your homework."},
    {term:"concentrate on", vi:"tập trung vào", ex:"It's hard to concentrate on your work when people are talking."},
    {term:"ambition", vi:"hoài bão, tham vọng", ex:"She has a lot of ambition; she wants to become a doctor."},
    {term:"self-analysis", vi:"tự phân tích bản thân", ex:"Self-analysis can help you understand what you need to improve."},
    {term:"role model", vi:"hình mẫu, tấm gương", ex:"Malala is a role model for many girls."},
    {term:"stereotype", vi:"định kiến, khuôn mẫu", ex:"That's just a stereotype."},
    {term:"defiant", vi:"ngang bướng, thách thức", ex:"He gave a defiant answer when asked to be quiet."},
    {term:"responsible", vi:"có trách nhiệm", ex:"Most teenagers are actually very responsible."},
    {term:"attitude", vi:"thái độ", ex:"What is the writer's attitude towards the protesters?"},
    {term:"petition", vi:"bản kiến nghị", ex:"They handed in a petition asking for change."},
    {term:"audience", vi:"khán giả, người nghe", ex:"Involve your audience right from the start."},
    {term:"rehearse", vi:"tập dượt, luyện tập trước", ex:"Rehearse your presentation carefully."},
    {term:"appreciate", vi:"trân trọng, biết ơn", ex:"I'd really appreciate your help with this."},
    {term:"brainstorm", vi:"động não, cùng nghĩ ý tưởng", ex:"Let's brainstorm some ideas together."}
  ],
  grammarNotes: [
    {title:"-ing form (Unit 1.1)", body:"Dùng -ing form sau một số động từ (enjoy, hate, mind, finish, stop) và sau giới từ (by, for, on, of, about, good at...):\nOur teachers don't mind us talking quietly.\nI sometimes get into trouble for chatting in class.\nCũng có thể dùng -ing form làm chủ ngữ của câu:\nSharing ideas helps me to learn."},
    {title:"Hiện tại đơn/tiếp diễn & thể bị động (Unit 1.3, 1.4, 1.6)", body:"Hiện tại đơn: thói quen, sự thật. Hiện tại tiếp diễn: việc đang diễn ra, lịch trình gần, và với 'always' để nhấn mạnh (khen/phàn nàn): He's always helping other people.\nThể bị động hiện tại đơn: We are told that... Modal + bị động: Young people should be given more freedom.\nThể bị động hiện tại tiếp diễn (is/are + being + p.p.): The art room is being used for an exhibition."},
    {title:"Kỹ năng đọc – viết – nói của Unit 1", body:"Đoán nghĩa từ qua ngữ cảnh (1.2); so sánh thái độ giữa hai bản tin về cùng sự kiện qua headline và cách chọn từ (1.5); cấu trúc một bài thuyết trình rõ ràng, trực quan (1.6); cấu trúc một email thân mật: mở đầu – lý do viết – kết thư (1.7); các bước hoàn thành một dự án nhóm (1.8)."}
  ],
  levels: [
    {id:1, icon:"🗣️", vn:"Kết nối 1.1 + 1.2: Lớp học & Tâm lý", en:"Link 1.1+1.2: classroom talk & psychology", blocks:[
      {kind:"boss", title:"🗣️🧠 Kết nối bài 1.1 + 1.2", instr:"Trộn từ vựng về nói chuyện trong lớp (1.1) và tâm lý tuổi teen (1.2).", items:[
        {kind:"mcq", q:"'distract' nghĩa là gì?", opts:["làm xao nhãng","khuyến khích","chia sẻ"], a:0},
        {kind:"mcq", q:"'creativity' nghĩa là gì?", opts:["sự sáng tạo","sự tập trung","giao tiếp"], a:0},
        {kind:"gapfill", s:"___ (share) ideas helps me to learn. (viết hoa chữ đầu)", a:"Sharing"},
        {kind:"gapfill", s:"She has a lot of ___; she wants to become a scientist.", a:"ambition"},
        {kind:"anagram", clue:"khuyến khích", scrambled:"UEOCAGERNC", answer:"encourage"},
        {kind:"anagram", clue:"sự tập trung", scrambled:"CUSFO", answer:"focus"}
      ]}
    ]},
    {id:2, icon:"⭐", vn:"Kết nối 1.3 + 1.4: Thần tượng & Định kiến", en:"Link 1.3+1.4: role models & stereotypes", blocks:[
      {kind:"boss", title:"⭐☁️ Kết nối bài 1.3 + 1.4", instr:"Trộn từ vựng về thần tượng (1.3) và định kiến tuổi teen (1.4).", items:[
        {kind:"mcq", q:"'stereotype' nghĩa là gì?", opts:["định kiến, khuôn mẫu","hình mẫu","tấm gương"], a:0},
        {kind:"mcq", q:"'responsible' nghĩa là gì?", opts:["có trách nhiệm","nổi loạn","thô lỗ"], a:0},
        {kind:"gapfill", s:"My role model ___ ___ (always/help) people who need advice.", a:"is always helping"},
        {kind:"gapfill", s:"We ___ (tell) that we behave worse than younger children.", a:"are told"},
        {kind:"classify", word:"Malala Yousafzai", ctx:"thần tượng của Sofia", cats:["Người nổi tiếng","Người trong gia đình"], cat:0},
        {kind:"anagram", clue:"ngang bướng, thách thức", scrambled:"TNAIFDE", answer:"defiant"}
      ]}
    ]},
    {id:3, icon:"📰", vn:"Kết nối 1.5 + 1.6: Báo chí & Thuyết trình", en:"Link 1.5+1.6: media & presentations", blocks:[
      {kind:"boss", title:"📰🎤 Kết nối bài 1.5 + 1.6", instr:"Trộn từ vựng về báo chí (1.5) và thuyết trình (1.6).", items:[
        {kind:"mcq", q:"'attitude' nghĩa là gì?", opts:["thái độ","ấn tượng","vấn đề"], a:0},
        {kind:"mcq", q:"'audience' nghĩa là gì?", opts:["khán giả, người nghe","hình ảnh minh họa","cấu trúc"], a:0},
        {kind:"gapfill", s:"They carried ___ with strong messages.", a:"placards"},
        {kind:"gapfill", s:"The art room ___ ___ ___ (use) for an exhibition right now.", a:"is being used"},
        {kind:"anagram", clue:"ấn tượng", scrambled:"OIPMSSNERI", answer:"impression"},
        {kind:"anagram", clue:"trang trình chiếu", scrambled:"EDSLI", answer:"slide"}
      ]}
    ]},
    {id:4, icon:"✉️", vn:"Kết nối 1.7 + 1.8: Email & Dự án", en:"Link 1.7+1.8: emails & projects", blocks:[
      {kind:"boss", title:"✉️🎬 Kết nối bài 1.7 + 1.8", instr:"Trộn từ vựng về viết email (1.7) và dự án cuối unit (1.8).", items:[
        {kind:"mcq", q:"'appreciate' nghĩa là gì?", opts:["trân trọng, biết ơn","tự hỏi","giữ liên lạc"], a:0},
        {kind:"mcq", q:"'draft' nghĩa là gì?", opts:["bản nháp","bản chính thức","kịch bản"], a:0},
        {kind:"gapfill", s:"The ___ I'm writing is to ask for your help.", a:"reason"},
        {kind:"gapfill", s:"Let's ___ some ideas together before we start writing.", a:"brainstorm"},
        {kind:"anagram", clue:"sự giúp đỡ, ân huệ", scrambled:"UROVAF", answer:"favour"},
        {kind:"anagram", clue:"phần kết luận", scrambled:"CONCLUSINO", answer:"conclusion"}
      ]}
    ]},
    {id:5, icon:"⚙️", vn:"Tổng ôn ngữ pháp cả Unit 1", en:"Whole-unit grammar summary", blocks:[
      {kind:"boss", title:"⚙️ Trận Boss: Tổng ôn ngữ pháp Unit 1", instr:"15 câu tổng hợp toàn bộ ngữ pháp đã học: -ing form (1.1), hiện tại đơn/tiếp diễn (1.3), thể bị động hiện tại đơn & modal (1.4), thể bị động tiếp diễn (1.6).", items:[
        {kind:"gapfill", s:"[1.1] I don't like ___ (interrupt) when someone is speaking.", a:"interrupting"},
        {kind:"gapfill", s:"[1.1] ___ (share) ideas helps me to learn. (viết hoa chữ đầu)", a:"Sharing"},
        {kind:"gapfill", s:"[1.1] She's good at ___ (compare) different opinions before making a decision.", a:"comparing"},
        {kind:"gapfill", s:"[1.3] At the moment, he ___ (help) children who have problems with their reading.", a:"is helping"},
        {kind:"gapfill", s:"[1.3] It ___ (depend) on what they're famous for.", a:"depends"},
        {kind:"gapfill", s:"[1.3] My role model ___ ___ (always/help) people who need advice.", a:"is always helping"},
        {kind:"gapfill", s:"[1.3] We ___ (go) to watch her give a talk next Saturday.", a:"are going"},
        {kind:"gapfill", s:"[1.4] We ___ (tell) that we behave worse than younger children.", a:"are told"},
        {kind:"gapfill", s:"[1.4] Defiant means you ___ (ask) to do something, and you refuse.", a:"are asked"},
        {kind:"gapfill", s:"[1.4] Teenagers often ___ ___ (think) to be irresponsible, but that's not always true.", a:"are thought"},
        {kind:"gapfill", s:"[1.4] Young people ___ ___ ___ (should/give) more freedom to make their own choices.", a:"should be given"},
        {kind:"gapfill", s:"[1.4] This word ___ ___ (can/use) to describe someone who refuses to do what they're told.", a:"can be used"},
        {kind:"gapfill", s:"[1.6] The art room ___ ___ ___ (use) for an exhibition at the moment.", a:"is being used"},
        {kind:"gapfill", s:"[1.6] A new drama studio ___ ___ ___ (build) at our school.", a:"is being built"},
        {kind:"gapfill", s:"[1.6] Drinks and snacks ___ ___ ___ (serve) in the small hall today.", a:"are being served"}
      ]}
    ]},
    {id:6, icon:"📝", vn:"Dịch báo thật: Rèn sự tự tin", en:"Translate a real article: building confidence", blocks:[
      {kind:"theory", title:"📝 Nguồn bài đọc", instr:"", html:"Đoạn văn dưới đây trích từ báo <b>Giáo dục &amp; Thời đại</b> (giaoducthoidai.vn), bài viết <i>\"Kỹ năng rèn luyện giúp con tự tin\"</i>. Em hãy dịch từng câu sang tiếng Anh, sau đó bấm 'Xong' và so sánh với gợi ý — không cần dịch giống 100%, miễn là đúng ý!"},
      {kind:"writing", title:"📝 Dịch các câu sau sang tiếng Anh", instr:"", tasks:[
        {prompt:"Dịch: \"Sự tự tin, khả năng giao tiếp là những kỹ năng quan trọng trong đời sống.\"", sample:"Confidence and communication skills are important skills in life."},
        {prompt:"Dịch: \"Tuy nhiên, chúng không tự sinh ra mà cần quá trình học tập và rèn luyện.\"", sample:"However, they don't appear naturally — they need a process of learning and practice."},
        {prompt:"Dịch: \"Tự tin là đức tính có được sau quá trình rèn luyện, dưới sự tác động của nhiều yếu tố.\"", sample:"Confidence is a quality gained after a process of practice, influenced by many factors."},
        {prompt:"Dịch: \"Rèn luyện sự tự tin cho con cần có thời gian, sự kiên trì và cả tính nhất quán.\"", sample:"Building a child's confidence takes time, patience and consistency."},
        {prompt:"Dịch: \"Mỗi đứa trẻ là một cá thể riêng biệt, sở hữu tính cách và những ưu điểm khác nhau.\"", sample:"Every child is a unique individual, with their own personality and strengths."}
      ]}
    ]},
    {id:7, icon:"👑", vn:"Trận Boss nâng cao: Toàn Unit 1", en:"Advanced boss: whole Unit 1", blocks:[
      {kind:"boss", title:"👑 Trận Boss nâng cao: Toàn Unit 1", instr:"Thử thách khó hơn — đọc kỹ trước khi chọn!", items:[
        {kind:"mcq", q:"Câu nào dùng -ing form làm CHỦ NGỮ của câu?", opts:["Talking too much in class can distract other students.","I don't like interrupting people.","She's good at comparing opinions."], a:0},
        {kind:"mcq", q:"Tiêu đề báo nào thể hiện thái độ TIÊU CỰC nhất về cuộc biểu tình?", opts:["\"Teenage rage\"","\"Take climate change seriously, say school students\"","\"protested peacefully\""], a:0},
        {kind:"gapfill", s:"Negative stereotypes ___ ___ ___ (should/not/believe) without evidence.", a:"should not be believed"},
        {kind:"gapfill", s:"The tickets for the show ___ ___ ___ (sell) online right now.", a:"are being sold"},
        {kind:"classify", word:"Jayden's grandad", ctx:"không phải người nổi tiếng, nhưng vẫn là role model được ngưỡng mộ", cats:["Người nổi tiếng (celebrity)","Người trong gia đình"], cat:1},
        {kind:"anagram", clue:"có ảnh hưởng lớn", scrambled:"LNAIFULTNENI", answer:"influential"},
        {kind:"anagram", clue:"bị cuốn hút, tham gia vào", scrambled:"DEEGAGN", answer:"engaged"}
      ]}
    ]}
  ]
}});
CG9.addLesson({id:"u2-connect", unit:2, type:"connect", src:"Tho Ket Noi Quest - Cambridge Global English 9 Unit 2 Mixed.html", game:{
  storageKey: "tho-mixed-cge9-u2-v1",
  brand: "Thỏ Kết Nối Quest",
  subtitle: "Cambridge Global English 9 – Unit 2 Well-being: Liên kết & Ngữ pháp nâng cao + Dịch Việt–Anh",
  mapTitle: "🔗 Bản đồ nâng cao: Kết nối cả Unit 2",
  mapIntro: "Khác với 'Thỏ Ôn Tập Quest' (ôn từng bài riêng lẻ), game này LIÊN KẾT các bài nhỏ với nhau, ôn TOÀN BỘ ngữ pháp trong Unit 2 gộp chung, và có 1 màn DỊCH đoạn văn từ tiếng Việt sang tiếng Anh. Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ, liên kết nội dung Cambridge Global English Learner's Book 9 & Workbook 9, Unit 2 Well-being (2.1–2.8). Đoạn văn tiếng Việt ở màn Dịch trích nguyên văn từ báo Sức khỏe & Đời sống (suckhoedoisong.vn – cơ quan ngôn luận của Bộ Y tế), bài 'Ăn gì cho đúng ở tuổi học đường?'. Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Kết Nối Unit 2",
  unlockAll: true,
  vocab: [
    {term:"balanced diet / junk food", vi:"chế độ ăn cân bằng / đồ ăn vặt không lành mạnh", ex:"A balanced diet is healthier than junk food."},
    {term:"exhausted / wind down", vi:"kiệt sức / thư giãn trước khi ngủ", ex:"She was exhausted because she didn't wind down before bed."},
    {term:"empathy / self-control", vi:"sự đồng cảm / khả năng tự kiềm chế", ex:"Empathy and self-control help you get on with others."},
    {term:"according to / be associated with", vi:"theo như / có liên quan đến", ex:"According to the study, stress is associated with poor sleep."},
    {term:"absolutely + tính từ mạnh", vi:"hoàn toàn/vô cùng + tính từ mạnh", ex:"I'm absolutely exhausted, not just tired!"},
    {term:"thực phẩm lành mạnh (healthy food)", vi:"food from natural sources, low in saturated fat, sugar and salt", ex:"Rau xanh và trái cây tươi là thực phẩm lành mạnh."}
  ],
  grammarNotes: [
    {title:"Less / Fewer", body:"less + danh từ không đếm được. fewer + danh từ đếm được số nhiều."},
    {title:"Danh từ trừu tượng + mạo từ", body:"Khi nói về 1 khái niệm chung chung (obesity, poverty...), KHÔNG dùng 'the' phía trước: 'Obesity is a problem', không phải 'The obesity is a problem'."},
    {title:"So sánh hơn (Comparatives)", body:"Ngắn: -er (healthier). Dài: more + tính từ (more important, more nutritious)."},
    {title:"must have / might have / can't have", body:"Suy đoán về quá khứ: chắc hẳn đã / có lẽ đã / không thể đã + V3."},
    {title:"Danh từ ↔ Tính từ", body:"anger→angry, annoyance→annoyed, empathy→empathetic, self-control→self-controlled."},
    {title:"Tính từ mạnh + từ nhấn mạnh", body:"Tính từ mạnh (exhausted, furious, ecstatic, freezing...) đi với absolutely/really, KHÔNG đi với very."},
    {title:"get + tính từ", body:"get anxious, get involved, get better/worse — diễn tả sự thay đổi trạng thái."}
  ],
  levels: [
    {id:1, icon:"🔗", vn:"Liên kết 2.1 + 2.2: Ăn uống & So sánh hơn", en:"Link 2.1+2.2", blocks:[
      {kind:"transform", title:"🔗 Dùng từ vựng 2.1 trong câu so sánh hơn (2.2)", instr:"", items:[
        {s:"Vegetables are (healthy) ______ than fast food.", root:"2.1 + 2.2", a:"healthier"},
        {s:"Eating breakfast is (important) ______ than skipping it, according to doctors.", root:"2.1 + 2.2", a:"more important"},
        {s:"This school cafeteria serves (nutritious) ______ food than it used to.", root:"2.1 + 2.2", a:"more nutritious"}
      ]},
      {kind:"mcq", title:"🔗 Trắc nghiệm liên kết 2.1 + 2.2", instr:"", questions:[
        {q:"A balanced diet usually contains ______ calories than a diet of junk food.", opts:["fewer","less","few"], a:0},
        {q:"Malnutrition is ______ in poorer countries than in richer ones.", opts:["more common","commoner","most common"], a:0},
        {q:"Drinking water is ______ for you than drinking soda, if you want to avoid extra calories.", opts:["better","gooder","more good"], a:0}
      ]}
    ]},
    {id:2, icon:"🔗", vn:"Liên kết 2.3 + 2.4: Giấc ngủ & Suy đoán", en:"Link 2.3+2.4", blocks:[
      {kind:"mcq", title:"🔗 Giấc ngủ (2.3) + must have/might have (2.4)", instr:"", questions:[
        {q:"He looks exhausted today. He ______ slept very well last night.", opts:["can't have","must have","might"], a:0},
        {q:"She seems anxious about the exam. She ______ stayed up all night studying instead of sleeping.", opts:["might have","can't have","doesn't"], a:0},
        {q:"Not sleeping enough is often associated with feeling ______.", opts:["anxious","delighted","ecstatic"], a:0},
        {q:"She's in a great mood today. She ______ finally caught up on sleep this week.", opts:["must have","can't have","doesn't have"], a:0}
      ]},
      {kind:"classify", title:"🔗 Nguyên nhân tâm trạng xấu có phải do thiếu ngủ không?", instr:"", cats:["Do thiếu ngủ (2.3)","Nguyên nhân khác"], items:[
        {word:"He was in a bad mood because he didn't wind down before bed and only slept 4 hours.", ctx:"", cat:0},
        {word:"He was in a bad mood because his team lost the football match.", ctx:"", cat:1},
        {word:"She felt exhausted and irritable after staying up all night on her phone.", ctx:"", cat:0},
        {word:"She felt annoyed because her brother borrowed her bike without asking.", ctx:"", cat:1}
      ]},
      {kind:"gapfill", title:"🔗 Điền từ", instr:"", wordbank:["exhausted"], items:[
        {pre:"Getting enough sleep helps prevent you from feeling", post:"during the day.", answers:["exhausted"]}
      ]}
    ]},
    {id:3, icon:"🔗", vn:"Liên kết 2.5 + 2.6: Tính cách & Hạnh phúc", en:"Link 2.5+2.6", blocks:[
      {kind:"transform", title:"🔗 Biến đổi từ (2.5) trong ngữ cảnh hạnh phúc (2.6)", instr:"", items:[
        {s:"empathy (n) → ______ (adj), a quality that helps you get on well with others.", root:"2.5 + 2.6", a:"empathetic"}
      ]},
      {kind:"mcq", title:"🔗 Trắc nghiệm liên kết 2.5 + 2.6", instr:"", questions:[
        {q:"If you always lose your temper, you might need more self-control. Try to get ______ in calming activities like yoga.", opts:["involved","married","anxious"], a:0},
        {q:"Which strong adjective means the same as 'very happy'?", opts:["ecstatic","annoyed","exhausted"], a:0}
      ]},
      {kind:"classify", title:"🔗 Tính từ thường hay Tính từ mạnh?", instr:"", cats:["Tính từ thường","Tính từ mạnh"], items:[
        {word:"furious", ctx:"", cat:1},
        {word:"angry", ctx:"", cat:0}
      ]},
      {kind:"tf", title:"🔗 Đúng hay Sai?", instr:"", items:[
        {s:"A supportive family can help you develop empathy and self-control.", a:true}
      ]},
      {kind:"gapfill", title:"🔗 Điền từ", instr:"", wordbank:["better"], items:[
        {pre:"After getting some rest, his mood started to get", post:".", answers:["better"]}
      ]}
    ]},
    {id:4, icon:"🔗", vn:"Liên kết 2.4 + 2.7 + 2.8: Suy đoán & Báo cáo", en:"Link 2.4+2.7+2.8", blocks:[
      {kind:"classify", title:"🔗 Câu này là Suy đoán quá khứ hay Ngôn ngữ báo cáo?", instr:"", cats:["Suy đoán quá khứ (2.4 / 2.7)","Ngôn ngữ báo cáo (2.8)"], items:[
        {word:"She must have been smiling in the photo because she had just won the competition.", ctx:"", cat:0},
        {word:"According to our survey, most students said they felt happier after a good night's sleep.", ctx:"", cat:1},
        {word:"In the photo, she looks relaxed. She must have just finished a peaceful holiday.", ctx:"", cat:0},
        {word:"We asked 50 students, and most of them said exercise made them feel better.", ctx:"", cat:1}
      ]},
      {kind:"gapfill", title:"🔗 Điền từ báo cáo (2.8)", instr:"", wordbank:["According"], items:[
        {pre:"", post:"to the study, sleep is closely associated with mood.", answers:["According"]}
      ]},
      {kind:"writing", title:"🔗 Viết 2 câu liên kết", instr:"", tasks:[
        {prompt:"Viết 1 câu suy đoán quá khứ (must have / might have / can't have) về 1 bức ảnh tưởng tượng, VÀ 1 câu dùng ngôn ngữ báo cáo (According to... / Most students said...) để trình bày 1 kết quả khảo sát.", sample:"1) She must have just finished a long swim — her hair is wet and she looks relaxed. 2) According to our survey, most students said a balanced diet made them feel more energetic."}
      ]}
    ]},
    {id:5, icon:"📚", vn:"Ngữ pháp tổng hợp TOÀN Unit 2", en:"All grammar in Unit 2", blocks:[
      {kind:"theory", title:"📚 Tất cả điểm ngữ pháp đã học trong Unit 2", instr:"", html:"1) <b>Less/Fewer</b>. 2) <b>Danh từ trừu tượng</b> — không dùng 'the' khi nói chung chung. 3) <b>So sánh hơn</b>. 4) <b>must have/might have/can't have</b>. 5) <b>Danh từ ↔ Tính từ</b>. 6) <b>Tính từ mạnh + absolutely/really</b> (không dùng very). 7) <b>get + tính từ</b>."},
      {kind:"mcq", title:"📚 Trắc nghiệm ngữ pháp tổng hợp (15 câu)", instr:"", questions:[
        {q:"I try to eat ______ sugar than before.", opts:["less","fewer","few"], a:0},
        {q:"There are ______ vegetarians in my class than last year.", opts:["fewer","less","little"], a:0},
        {q:"Choose the correct sentence.", opts:["Obesity is a growing problem among teenagers.","The obesity is a growing problem among teenagers.","An obesity is a growing problem among teenagers."], a:0},
        {q:"Choose the correct sentence.", opts:["Poverty can lead to malnutrition.","The poverty can lead to malnutrition.","A poverty can lead to the malnutrition."], a:0},
        {q:"A balanced diet is (important) ______ than fast food.", opts:["more important","importanter","most important"], a:0},
        {q:"He recovered (quickly) ______ than expected.", opts:["more quickly","quicklier","most quickly"], a:0},
        {q:"She's smiling. She ______ passed the exam.", opts:["must have","can't have","doesn't have"], a:0},
        {q:"He looks confused. He ______ understood the instructions.", opts:["can't have","must have","might"], a:0},
        {q:"I'm not sure, but he ______ forgotten about the meeting.", opts:["might have","must have","can't"], a:0},
        {q:"anger (n) → ______ (adj)", opts:["angry","angried","angriness"], a:0},
        {q:"empathy (n) → ______ (adj)", opts:["empathetic","empathy-ish","empathized"], a:0},
        {q:"Which intensifier is correct with the strong adjective 'exhausted'?", opts:["absolutely","very","quite"], a:0},
        {q:"Choose the correct sentence.", opts:["I'm absolutely starving!","I'm very starving!","I'm quite starving!"], a:0},
        {q:"He always gets ______ before a big test.", opts:["anxious","anxiety","anxiously"], a:0},
        {q:"Without enough sleep, his mood got ______.", opts:["worse","worst","more bad"], a:0}
      ]}
    ]},
    {id:6, icon:"🇻🇳➡️🇬🇧", vn:"Dịch đoạn văn: Ăn uống lành mạnh", en:"Translate: healthy eating", blocks:[
      {kind:"theory", title:"🇻🇳➡️🇬🇧 Nguồn đoạn văn", instr:"", html:"Đoạn văn dưới đây trích NGUYÊN VĂN từ báo <b>Sức khỏe & Đời sống</b> (suckhoedoisong.vn – cơ quan ngôn luận của Bộ Y tế), bài <i>\"Ăn gì cho đúng ở tuổi học đường?\"</i>. Đây là nguồn chính thống, tiếng Việt chuẩn, nội dung phù hợp với học sinh."},
      {kind:"passage", title:"🇻🇳 Đoạn văn cần dịch", instr:"", text:"Thực phẩm học sinh sử dụng mỗi ngày không chỉ ảnh hưởng đến thể lực trước mắt mà còn quyết định nền tảng sức khỏe lâu dài. Thực phẩm lành mạnh là những thực phẩm có nguồn gốc tự nhiên, ít chất béo bão hòa, ít chất béo chuyển hóa, ít đường tự do và ít muối. Rau xanh và củ quả là nguồn cung cấp vitamin và khoáng chất quan trọng. Trái cây tươi được khuyến khích sử dụng như một món tráng miệng lành mạnh thay cho bánh kẹo đóng gói. Nhiều học sinh hình thành thói quen bỏ bữa chính nhưng lại ăn rất nhiều đồ ăn vặt. Thay nước ngọt có gas bằng nước lọc. Thay bánh kẹo bằng trái cây. Thay đồ chiên rán bằng món luộc, hấp."},
      {kind:"writing", title:"🇬🇧 Dịch đoạn văn trên sang tiếng Anh", instr:"Cố gắng dùng từ vựng đã học trong Unit 2: balanced diet, healthy, junk food, skip a meal, vitamins, calories...", tasks:[
        {prompt:"Dịch cả đoạn văn tiếng Việt ở trên sang tiếng Anh. Không cần dịch từng chữ — quan trọng là đúng ý và dùng đúng từ vựng/ngữ pháp đã học.", sample:"The food that students eat every day not only affects their physical fitness in the short term, but also determines their long-term health. Healthy food is food that comes from natural sources, with little saturated fat, little trans fat, little added sugar and little salt. Green vegetables and other vegetables are an important source of vitamins and minerals. Fresh fruit is recommended as a healthy dessert instead of packaged sweets. Many students have formed the habit of skipping main meals but eating a lot of junk food instead. Replace fizzy drinks with water. Replace sweets with fruit. Replace fried food with boiled or steamed food."}
      ]}
    ]},
    {id:7, icon:"👑", vn:"Trận Boss nâng cao: Liên kết + Ngữ pháp + Dịch", en:"Advanced boss", blocks:[
      {kind:"boss", title:"👑 Trận Boss nâng cao: Toàn bộ Unit 2", instr:"", items:[
        {kind:"mcq", q:"Vegetables are ______ than fast food.", opts:["healthier","healther","more healther"], a:0},
        {kind:"mcq", q:"He looks exhausted. He ______ slept well last night.", opts:["can't have","must have","might"], a:0},
        {kind:"mcq", q:"Choose the correct sentence.", opts:["Obesity is a growing problem.","The obesity is a growing problem.","An obesity is a growing problem."], a:0},
        {kind:"gapfill", s:"empathy (n) → ___________ (adj)", a:"empathetic"},
        {kind:"mcq", q:"Which intensifier is correct with 'exhausted'?", opts:["absolutely","very","quite"], a:0},
        {kind:"classify", word:"According to the survey, students feel happier after exercise.", ctx:"", cats:["Suy đoán quá khứ","Ngôn ngữ báo cáo"], cat:1},
        {kind:"classify", word:"She must have just finished a run — she looks tired.", ctx:"", cats:["Suy đoán quá khứ","Ngôn ngữ báo cáo"], cat:0},
        {kind:"mcq", q:"How do you say 'thực phẩm lành mạnh' in English?", opts:["healthy food","junk food","fast food"], a:0},
        {kind:"mcq", q:"How do you say 'thay đồ ăn vặt bằng trái cây' in English?", opts:["replace junk food with fruit","replace fruit with junk food","avoid fruit"], a:0},
        {kind:"gapfill", s:"Without enough sleep, his mood got ___________.", a:"worse"}
      ]}
    ]}
  ]
}});
CG9.addLesson({id:"u3-connect", unit:3, type:"connect", src:"Tho Ket Noi Quest - Cambridge Global English 9 Unit 3 Mixed.html", game:{
  storageKey: "tho-mixed-cge9-u3-v1",
  brand: "Thỏ Kết Nối Quest",
  subtitle: "Cambridge Global English 9 – Unit 3 Tourism: Liên kết & Ngữ pháp nâng cao + Dịch Việt–Anh",
  mapTitle: "🔗 Bản đồ nâng cao: Kết nối cả Unit 3",
  mapIntro: "Khác với 'Thỏ Ôn Tập Quest' (ôn từng bài riêng lẻ), game này LIÊN KẾT các bài nhỏ với nhau, ôn TOÀN BỘ ngữ pháp trong Unit 3 gộp chung, và có 1 màn DỊCH các quy tắc du lịch từ tiếng Việt sang tiếng Anh. Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ, liên kết nội dung Cambridge Global English Learner's Book 9, Unit 3 Tourism (3.1–3.8). Đoạn dịch ở màn Dịch trích NGUYÊN VĂN từ Điều 3 và Điều 4, Quyết định số 718/QĐ-BVHTTDL ngày 02/3/2017 của Bộ Văn hóa, Thể thao và Du lịch, ban hành \"Bộ quy tắc ứng xử văn minh du lịch\" (văn bản quy phạm pháp luật của Nhà nước). Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Kết Nối Unit 3",
  unlockAll: true,
  vocab: [
    {term:"eco hotel / theme park / swimming pool", vi:"khách sạn sinh thái / công viên giải trí / hồ bơi", ex:"Compound nouns like these describe holiday places."},
    {term:"palace / fresco / amphitheatre", vi:"cung điện / tranh bích họa / đấu trường", ex:"We can use compound nouns to talk about art and architecture too."},
    {term:"break down / was being fixed", vi:"hỏng xe / đang được sửa", ex:"The car broke down, and it was being fixed while we waited at a family-run café."},
    {term:"family-run / open-minded / endangered species", vi:"do gia đình điều hành / cởi mở / loài nguy cấp", ex:"A responsible tourist stays at family-run hotels and never buys products from endangered species."},
    {term:"conservation / monitor / exciting vs excited", vi:"bảo tồn / giám sát / thú vị (t/c) vs hào hứng (c/x)", ex:"Conservation work can be exciting, and volunteers often feel excited to monitor wild animals."},
    {term:"worrying vs worried / infrastructure", vi:"đáng lo (t/c) vs lo lắng (c/x) / cơ sở hạ tầng", ex:"The worrying rise in litter makes local residents worried about the infrastructure."},
    {term:"towards / along / through / into / round", vi:"hướng về / dọc theo / xuyên qua / vào trong / vòng quanh", ex:"We headed towards the coast, along the river, through a forest, into the old town."},
    {term:"formal vs informal / a great success", vi:"trang trọng vs thân mật / một thành công lớn", ex:"In a formal report, say 'a great success', not 'absolutely amazing'."},
    {term:"tuân thủ / niêm yết giá / nội quy", vi:"to comply with / to post prices publicly / rules and regulations", ex:"Tourists should tuân thủ nội quy, and businesses should niêm yết giá công khai."}
  ],
  grammarNotes: [
    {title:"Danh từ ghép & cụm động từ (3.1)", body:"Danh từ ghép: beach umbrella, swimming pool. Cụm động từ: look round, catch up with, look forward to."},
    {title:"Nghệ thuật & Kiến trúc (3.2)", body:"palace, fresco, amphitheatre, the medieval period, the Renaissance."},
    {title:"Quá khứ tiếp diễn bị động (3.3)", body:"was/were + being + V3: The car was being fixed while we waited."},
    {title:"Tính từ ghép (3.4)", body:"family-run, locally made, homemade, open-minded, environmentally sensitive."},
    {title:"Từ vựng bảo tồn (3.5)", body:"conservation, monitor, neglect, mistreated, malnourished, coexistence."},
    {title:"Tính từ phân từ -ing/-ed (3.6)", body:"-ing = tính chất (worrying), -ed = cảm xúc (worried)."},
    {title:"Giới từ chỉ chuyển động (3.7)", body:"towards, along, through, into, round/around."},
    {title:"Trang trọng vs thân mật (3.8)", body:"Nói: 'absolutely amazing'. Viết báo cáo: 'a great success'."}
  ],
  levels: [
    {id:1, icon:"🔗", vn:"Liên kết 3.1 + 3.2: Kỳ nghỉ & Nghệ thuật", en:"Link 3.1+3.2", blocks:[
      {kind:"classify", title:"🔗 Từ này là Danh từ ghép về Kỳ nghỉ hay về Nghệ thuật/Kiến trúc?", instr:"", cats:["Kỳ nghỉ (3.1)","Nghệ thuật/Kiến trúc (3.2)"], items:[
        {word:"eco hotel", ctx:"", cat:0},
        {word:"amphitheatre", ctx:"", cat:1},
        {word:"theme park", ctx:"", cat:0},
        {word:"fresco", ctx:"", cat:1},
        {word:"swimming pool", ctx:"", cat:0},
        {word:"palace", ctx:"", cat:1}
      ]},
      {kind:"mcq", title:"🔗 Trắc nghiệm liên kết 3.1 + 3.2", instr:"", questions:[
        {q:"After cycling all day, Elena could have ______ in Mantua for another week — she loved the frescoes so much.", opts:["stayed on","taken off","broken down"], a:0},
        {q:"We're looking forward ______ seeing the amazing Roman amphitheatre in Verona.", opts:["to","for","at"], a:0},
        {q:"A ______ is a kind of accommodation, while a ______ is a kind of painting on a wall.", opts:["theme park / fresco","fresco / theme park","palace / palace"], a:0}
      ]}
    ]},
    {id:2, icon:"🔗", vn:"Liên kết 3.3 + 3.4: Trục trặc & Du lịch có trách nhiệm", en:"Link 3.3+3.4", blocks:[
      {kind:"transform", title:"🔗 Dùng quá khứ tiếp diễn bị động (3.3) để kể về chỗ ở có trách nhiệm (3.4)", instr:"", items:[
        {s:"Someone was repairing our family-run hotel room when we arrived. →\n______", root:"WAS BEING", a:"Our family-run hotel room was being repaired when we arrived."},
        {s:"Someone was checking the locally made souvenirs at the shop. →\n______", root:"WERE BEING", a:"The locally made souvenirs were being checked at the shop."}
      ]},
      {kind:"classify", title:"🔗 Có trách nhiệm (3.4) hay chỉ là trục trặc (3.3)?", instr:"", cats:["Du lịch có trách nhiệm (3.4)","Trục trặc kỳ nghỉ (3.3)"], items:[
        {word:"staying at family-run accommodation", ctx:"", cat:0},
        {word:"the taxi never turned up", ctx:"", cat:1},
        {word:"buying locally made souvenirs", ctx:"", cat:0},
        {word:"the car broke down in a village", ctx:"", cat:1}
      ]}
    ]},
    {id:3, icon:"🔗", vn:"Liên kết 3.5 + 3.6: Bảo tồn & Cảm xúc về du lịch", en:"Link 3.5+3.6", blocks:[
      {kind:"mcq", title:"🔗 Trắc nghiệm liên kết 3.5 + 3.6", instr:"", questions:[
        {q:"Volunteering on an elephant conservation project is really ______ — you learn so much!", opts:["exciting","excited","exciting of"], a:0},
        {q:"Many volunteers feel ______ about monitoring endangered elephants every day.", opts:["excited","exciting","excite"], a:0},
        {q:"The ______ rise in habitat loss is one reason conservation projects need volunteers.", opts:["worrying","worried","worry"], a:0}
      ]},
      {kind:"classify", title:"🔗 Câu này ủng hộ (FOR) hay phản đối (AGAINST) du lịch, dựa trên công việc bảo tồn?", instr:"", cats:["FOR (ủng hộ)","AGAINST (phản đối)"], items:[
        {word:"Volunteer tourism brings money for conservation projects.", ctx:"", cat:0},
        {word:"Too many tourists can disturb wildlife and habitats.", ctx:"", cat:1},
        {word:"Monitoring and protecting elephants helps peaceful coexistence.", ctx:"", cat:0}
      ]}
    ]},
    {id:4, icon:"🔗", vn:"Liên kết 3.7 + 3.8: Hành trình & Báo cáo trang trọng", en:"Link 3.7+3.8", blocks:[
      {kind:"gapfill", title:"🔗 Điền giới từ chuyển động (3.7) vào đoạn báo cáo trang trọng (3.8)", instr:"", wordbank:["towards","through","into","along"], items:[
        {pre:"Our group travelled", post:"the national park to carry out a wildlife conservation project.", answers:["through"]},
        {pre:"We headed", post:"the nature reserve early in the morning.", answers:["towards"]},
        {pre:"By midday we had walked", post:"the forest and arrived at the research station.", answers:["into"]},
        {pre:"We walked", post:"the river, planting trees as we went.", answers:["along"]}
      ]},
      {kind:"classify", title:"🔗 Câu nào phù hợp để viết trong BÁO CÁO (trang trọng)?", instr:"", cats:["Phù hợp cho báo cáo (formal)","Chỉ dùng khi nói (informal)"], items:[
        {word:"The trip was a great success.", ctx:"", cat:0},
        {word:"It was absolutely amazing!", ctx:"", cat:1},
        {word:"We found the project very beneficial.", ctx:"", cat:0},
        {word:"We were just hanging out most days.", ctx:"", cat:1}
      ]}
    ]},
    {id:5, icon:"📚", vn:"Ngữ pháp tổng hợp TOÀN Unit 3", en:"All grammar in Unit 3", blocks:[
      {kind:"theory", title:"📚 Tất cả điểm ngữ pháp đã học trong Unit 3", instr:"", html:"1) <b>Danh từ ghép & cụm động từ</b> (3.1). 2) <b>Tính từ ghép</b> (3.4). 3) <b>Quá khứ tiếp diễn bị động</b> (was/were being + V3) (3.3). 4) <b>Tính từ phân từ -ing/-ed</b> (3.6). 5) <b>Giới từ chỉ chuyển động</b> (3.7). 6) <b>Trang trọng vs thân mật</b> (3.8)."},
      {kind:"mcq", title:"📚 Trắc nghiệm ngữ pháp tổng hợp (15 câu)", instr:"", questions:[
        {q:"You can ______ the shops this afternoon if you want to.", opts:["look round","look at round","look rounds"], a:0},
        {q:"I could have ______ in Mantua for another week!", opts:["stayed on","stay on","staying on"], a:0},
        {q:"The dinner ______ prepared while the guests were arriving.", opts:["was being","was been","were being"], a:0},
        {q:"Our passports ______ checked at the airport for almost an hour.", opts:["were being","was being","are being"], a:0},
        {q:"We stayed at a lovely ______ guesthouse near the beach.", opts:["family-run","family-ran","family-running"], a:0},
        {q:"I bought some ______ pottery as a souvenir, made in the village itself.", opts:["locally made","locally make","local making"], a:0},
        {q:"Going to a new country is really ______.", opts:["exciting","excited","excite"], a:0},
        {q:"I'm really ______ about our trip next week!", opts:["excited","exciting","excite"], a:0},
        {q:"The rise in pollution is extremely ______.", opts:["worrying","worried","worry"], a:0},
        {q:"Local residents are ______ about losing their town's identity.", opts:["worried","worrying","worry"], a:0},
        {q:"We headed ______ the mountains in the distance.", opts:["towards","into","along"], a:0},
        {q:"We cycled ______ the river for two hours.", opts:["along","into","towards"], a:0},
        {q:"We finally walked ______ the old town.", opts:["into","along","round"], a:0},
        {q:"In a written report, it's better to say the trip was 'a great success' than ______.", opts:["'absolutely amazing'","'a positive outcome'","'highly beneficial'"], a:0},
        {q:"Instead of saying we were 'hanging out' with friends, a formal report should say ______.", opts:["'enjoying being together'","'chilling'","'hanging around'"], a:0}
      ]}
    ]},
    {id:6, icon:"🇻🇳➡️🇬🇧", vn:"Dịch: Bộ quy tắc ứng xử văn minh du lịch", en:"Translate: tourist code of conduct", blocks:[
      {kind:"theory", title:"🇻🇳➡️🇬🇧 Nguồn các câu dưới đây", instr:"", html:"Các câu dưới đây trích NGUYÊN VĂN từ Điều 3 (Quy tắc ứng xử của khách du lịch) và Điều 4 (Quy tắc ứng xử của tổ chức, cá nhân kinh doanh du lịch) trong <b>Quyết định số 718/QĐ-BVHTTDL</b> ngày 02/3/2017 của <b>Bộ Văn hóa, Thể thao và Du lịch</b>, ban hành \"Bộ quy tắc ứng xử văn minh du lịch\". Đây là văn bản quy phạm pháp luật của Nhà nước, chủ đề khớp với bài 3.4 Responsible tourism."},
      {kind:"passage", title:"🇻🇳 Các quy tắc cần dịch", instr:"", text:"1. Tuân thủ các quy định, nội quy hoạt động, biển báo, hướng dẫn của người quản lý tại điểm đến.\n2. Tôn trọng văn hóa, tôn giáo, tín ngưỡng, phong tục, tập quán của cộng đồng địa phương tại điểm đến.\n3. Không vứt rác, khạc nhổ, đi vệ sinh bừa bãi và hút thuốc lá ở những nơi không được phép.\n4. Không sử dụng sản phẩm từ các loài động, thực vật hoang dã, các loài cần được bảo vệ.\n5. Niêm yết công khai và bán đúng giá dịch vụ, không bán cao hơn giá niêm yết.\n6. Không lợi dụng thời điểm đông khách để nâng giá, ép giá, cung cấp dịch vụ kém chất lượng cho khách du lịch.\n7. Không xả thải, sử dụng nguyên vật liệu gây tác động xấu tới môi trường."},
      {kind:"writing", title:"🇬🇧 Dịch 7 quy tắc trên sang tiếng Anh", instr:"Cố gắng dùng từ vựng/ngữ pháp đã học trong Unit 3: litter, endangered species, environmentally sensitive, local economy, câu bị động, 'should'/'must not'...", tasks:[
        {prompt:"Dịch quy tắc 1, 2 và 3 sang tiếng Anh.", sample:"1. Follow the rules, regulations, signs and guidance given by the managers at the destination.\n2. Respect the culture, religion, beliefs and customs of the local community at the destination.\n3. Do not litter, spit or go to the toilet in inappropriate places, and do not smoke where it is not allowed."},
        {prompt:"Dịch quy tắc 4, 5, 6 và 7 sang tiếng Anh.", sample:"4. Do not use products made from wild animals or plants, especially endangered species that need protection.\n5. Publicly display prices and sell services at the correct price — do not charge more than the listed price.\n6. Do not take advantage of busy periods to raise prices, overcharge, or provide poor-quality services to tourists.\n7. Do not discharge waste or use materials that have a bad effect on the environment."}
      ]}
    ]},
    {id:7, icon:"👑", vn:"Trận Boss nâng cao: Liên kết + Ngữ pháp + Dịch", en:"Advanced boss", blocks:[
      {kind:"boss", title:"👑 Trận Boss nâng cao: Toàn bộ Unit 3", instr:"", items:[
        {kind:"mcq", q:"You can ______ the shops this afternoon.", opts:["look round","look at round","look rounds"], a:0},
        {kind:"mcq", q:"A picture painted directly onto a wet wall is called a ______.", opts:["fresco","ceiling","palace"], a:0},
        {kind:"gapfill", s:"The car ___ being fixed while we waited. (was/were)", a:"was"},
        {kind:"mcq", q:"We stayed at a lovely ______ guesthouse near the beach.", opts:["family-run","family-ran","family-running"], a:0},
        {kind:"classify", word:"Buying souvenirs made from endangered species", ctx:"", cats:["Có trách nhiệm","Không có trách nhiệm"], cat:1},
        {kind:"mcq", q:"Going to a new country is really ______.", opts:["exciting","excited","excite"], a:0},
        {kind:"gapfill", s:"The rise in pollution is extremely ___. (tính chất)", a:"worrying"},
        {kind:"mcq", q:"We headed ______ the mountains in the distance.", opts:["towards","into","along"], a:0},
        {kind:"classify", word:"It was a great success.", ctx:"", cats:["Trang trọng","Thân mật"], cat:0},
        {kind:"anagram", clue:"sự chung sống hoà bình", scrambled:"OICEXCEETNSE", answer:"coexistence"},
        {kind:"gapfill", s:"How do you say 'loài có nguy cơ tuyệt chủng' in English? (2 từ)", a:"endangered species"},
        {kind:"mcq", q:"According to the tourist code of conduct, tourists should NOT buy products made from ______.", opts:["wild/endangered species","locally made souvenirs","family-run shops"], a:0}
      ]}
    ]}
  ]
}});
CG9.addLesson({id:"u4-connect", unit:4, type:"connect", src:"Tho Ket Noi Quest - Cambridge Global English 9 Unit 4 Mixed.html", game:{
  storageKey: "tho-mixed-cge9-u4-v1",
  brand: "Thỏ Kết Nối Quest",
  subtitle: "Cambridge Global English 9 – Unit 4 Science: Liên kết & Ngữ pháp nâng cao + Dịch Việt–Anh",
  mapTitle: "🔗 Bản đồ nâng cao: Kết nối cả Unit 4",
  mapIntro: "Khác với 'Thỏ Ôn Tập Quest' (ôn từng bài riêng lẻ), game này LIÊN KẾT các bài nhỏ với nhau, ôn TOÀN BỘ ngữ pháp trong Unit 4 gộp chung, và có 1 màn DỊCH đoạn văn từ tiếng Việt sang tiếng Anh. Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ, liên kết nội dung Cambridge Global English Learner's Book 9, Unit 4 Science (4.1–4.8). Đoạn văn tiếng Việt ở màn Dịch trích nguyên văn từ báo Sức khỏe & Đời sống (suckhoedoisong.vn – cơ quan ngôn luận của Bộ Y tế), bài 'Vườn quốc gia Bạch Mã cứu hộ, tái thả về tự nhiên nhiều cá thể động vật quý hiếm'. Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Kết Nối Unit 4",
  unlockAll: true,
  vocab: [
    {term:"receptor / colour-blind", vi:"thụ thể / mù màu", ex:"Colour-blindness happens when a receptor doesn't work properly."},
    {term:"quarantine / vaccination", vi:"cách ly / tiêm chủng", ex:"Quarantine and vaccination both help control a pandemic."},
    {term:"unique / human genome", vi:"độc nhất / bộ gen người", ex:"Everyone's human genome is unique, like a fingerprint."},
    {term:"invention / endangered species", vi:"phát minh / loài nguy cấp", ex:"Richard's invention protects endangered species like lions."},
    {term:"objective / biased", vi:"khách quan / thiên vị", ex:"A good article should be objective, not biased."},
    {term:"suffer from / depend on", vi:"chịu đựng, bị / phụ thuộc vào", ex:"Wild animals suffer from stress in small cages, and their survival depends on habitat protection."},
    {term:"however / in conclusion", vi:"tuy nhiên / kết luận", ex:"However, cages can feel like a prison. In conclusion, zoos need to improve."},
    {term:"cứu hộ / tái thả về tự nhiên", vi:"rescue / release back into the wild", ex:"Vườn quốc gia Bạch Mã cứu hộ và tái thả nhiều cá thể động vật quý hiếm."}
  ],
  grammarNotes: [
    {title:"Liên từ + V-ing (4.1)", body:"after/before/when/while + V-ing khi 2 mệnh đề cùng chủ ngữ."},
    {title:"Câu bị động hiện tại/quá khứ đơn (4.2)", body:"be + P.P. Dùng để nói về sự kiện lịch sử y học."},
    {title:"Hiện tại hoàn thành tiếp diễn (4.3)", body:"have/has been + V-ing — việc bắt đầu trong quá khứ, còn tiếp diễn."},
    {title:"Hiện tại hoàn thành chủ động & bị động (4.4)", body:"Chủ động: have/has + P.P. Bị động: have/has been + P.P."},
    {title:"Objective/Biased (4.5)", body:"objective = khách quan, có số liệu/nguồn. biased = thiên vị, dùng cảm xúc cá nhân."},
    {title:"Giới từ đi sau động từ (4.6)", body:"suffer from, agree with, approve of, depend on, specialise in."},
    {title:"Từ nối (4.7)", body:"First/In addition/Finally (liệt kê); However/although (trái ngược); In conclusion (kết luận)."}
  ],
  levels: [
    {id:1, icon:"🔗", vn:"Liên kết 4.1 + 4.2: Màu sắc & Bệnh dịch", en:"Link 4.1+4.2", blocks:[
      {kind:"transform", title:"🔗 Dùng liên từ + V-ing (4.1) để kể về lịch sử y học (4.2)", instr:"", items:[
        {s:"After ______ that milkmaids with cowpox didn't get smallpox, Jenner decided to test his idea.", root:"notice", a:"noticing"},
        {s:"Before ______ the smallpox vaccine to the world, Jenner tested it carefully on one boy.", root:"give", a:"giving"},
        {s:"While ______ about colour receptors in the eye, scientists also learned about eye diseases.", root:"learn", a:"learning"}
      ]},
      {kind:"mcq", title:"🔗 Trắc nghiệm liên kết 4.1 + 4.2", instr:"", questions:[
        {q:"Colour-blindness happens when a ______ in the eye doesn't work properly — similar to how a disease happens when the body doesn't fight it off.", opts:["receptor","antibiotic","quarantine"], a:0},
        {q:"By 1853, vaccination against smallpox ______ compulsory in Britain.", opts:["had become","have become","has become"], a:0},
        {q:"Most people ______ against smallpox during the 20th century, before it was eradicated.", opts:["were vaccinated","are vaccinated","vaccinate"], a:0}
      ]}
    ]},
    {id:2, icon:"🔗", vn:"Liên kết 4.3 + 4.4: DNA & Lion Lights", en:"Link 4.3+4.4", blocks:[
      {kind:"classify", title:"🔗 Hiện tại hoàn thành TIẾP DIỄN hay BỊ ĐỘNG?", instr:"", cats:["Tiếp diễn (4.3 style)","Bị động (4.4 style)"], items:[
        {word:"We've been learning about DNA and genetics all week.", ctx:"", cat:0},
        {word:"Many lions have been killed by farmers trying to protect their animals.", ctx:"", cat:1},
        {word:"Rian has been finding out a lot about fingerprints recently.", ctx:"", cat:0},
        {word:"Crops have been protected from elephants by Richard's lion lights.", ctx:"", cat:1}
      ]},
      {kind:"mcq", title:"🔗 Trắc nghiệm liên kết 4.3 + 4.4", instr:"", questions:[
        {q:"Which word describes something 'the only one of its kind' — true of both a fingerprint AND Richard's invention?", opts:["unique","common","typical"], a:0},
        {q:"Richard's invention ______ him famous, just like a scientific discovery can make a scientist famous.", opts:["has made","have made","has been made"], a:0}
      ]}
    ]},
    {id:3, icon:"🔗", vn:"Liên kết 4.5 + 4.6: Tuyệt chủng & Sở thú", en:"Link 4.5+4.6", blocks:[
      {kind:"classify", title:"🔗 Câu này về sở thú là Khách quan hay Thiên vị?", instr:"", cats:["Khách quan (có số liệu/nguồn)","Thiên vị (chỉ là ý kiến)"], items:[
        {word:"Zoos have succeeded in breeding giant pandas, with around 1800 now living in the wild.", ctx:"", cat:0},
        {word:"People who are against zoos just don't understand animals at all.", ctx:"", cat:1},
        {word:"A study found that captive breeding programmes have helped rhino numbers increase from under 100 to around 21,000.", ctx:"", cat:0}
      ]},
      {kind:"gapfill", title:"🔗 Điền giới từ (4.6) trong ngữ cảnh tuyệt chủng (4.5)", instr:"", items:[
        {pre:"Endangered species can be protected", post:"extinction by good zoo breeding programmes.", answers:["from"]},
        {pre:"The survival of many species depends", post:"funding and public support for conservation.", answers:["on"]}
      ]}
    ]},
    {id:4, icon:"🔗", vn:"Liên kết 4.6 + 4.7 + 4.8: Sở thú, Viết luận & Dự án", en:"Link 4.6+4.7+4.8", blocks:[
      {kind:"gapfill", title:"🔗 Điền từ nối (4.7) trong đoạn giới thiệu dự án fact file (4.8)", instr:"", items:[
        {pre:"", post:", the Amur leopard is critically endangered, with only around 84 left in the wild. (liệt kê ý đầu)", answers:["First"]},
        {pre:"", post:", zoos and wildlife parks like 'Land of the Leopard' can help protect the species from extinction. (thêm ý)", answers:["In addition","Furthermore"]},
        {pre:"", post:", some people believe it would be better to protect the leopard's natural habitat instead of relying on zoos. (trái ngược)", answers:["However"]}
      ]},
      {kind:"writing", title:"🔗 Viết đoạn văn ngắn liên kết cả 3 bài", instr:"", tasks:[
        {prompt:"Viết 3-4 câu giới thiệu 1 dự án fact file về loài nguy cấp, dùng ít nhất 2 từ nối (First, In addition, However, In conclusion) VÀ ít nhất 1 từ vựng về sở thú (enclosure, breed, release into the wild...).", sample:"First, I chose the Amur leopard for my fact file because it is critically endangered. In addition, I learned that some zoos breed leopards and release them into the wild. However, I believe protecting their natural habitat is even more important than breeding in zoos."}
      ]}
    ]},
    {id:5, icon:"📚", vn:"Ngữ pháp tổng hợp TOÀN Unit 4", en:"All grammar in Unit 4", blocks:[
      {kind:"theory", title:"📚 Tất cả điểm ngữ pháp đã học trong Unit 4", instr:"", html:"1) <b>Liên từ + V-ing</b> (after/before/when/while). 2) <b>Câu bị động hiện tại/quá khứ đơn</b>. 3) <b>Hiện tại hoàn thành tiếp diễn</b> (have/has been + V-ing). 4) <b>Hiện tại hoàn thành chủ động & bị động</b>. 5) <b>Giới từ đi sau động từ</b>. 6) <b>Từ nối (connectives)</b>."},
      {kind:"mcq", title:"📚 Trắc nghiệm ngữ pháp tổng hợp (15 câu)", instr:"", questions:[
        {q:"______ answering the questions, read the whole text carefully.", opts:["Before","During","For"], a:0},
        {q:"While ______ in different countries, people often use different colour words.", opts:["living","live","lived"], a:0},
        {q:"Most children ______ against measles and polio.", opts:["are vaccinated","vaccinate","vaccinated"], a:0},
        {q:"A link ______ between contaminated water and cholera in the 19th century.", opts:["was discovered","discovered","discovers"], a:0},
        {q:"We ______ about DNA and genetics all week.", opts:["have been learning","learn","learned"], a:0},
        {q:"Look at your hands — you ______ again!", opts:["have been painting","paint","painted"], a:0},
        {q:"Richard's invention ______ him famous.", opts:["has made","have made","has been made"], a:0},
        {q:"Many lions ______ by farmers trying to protect their animals.", opts:["have been killed","have killed","kill"], a:0},
        {q:"Choose the more objective sentence.", opts:["A study found that 60% of large herbivores are at risk of extinction.","People who don't care about animals are just selfish.","Everyone knows zoos are always bad."], a:0},
        {q:"Animals in zoos can suffer ______ stress and boredom.", opts:["from","with","for"], a:0},
        {q:"I don't approve ______ keeping wild animals in small cages.", opts:["of","with","in"], a:0},
        {q:"The survival of many species depends ______ people protecting their habitats.", opts:["on","of","from"], a:0},
        {q:"______, zoos help protect endangered species from extinction. (liệt kê ý đầu)", opts:["First","However","In addition"], a:0},
        {q:"Zoos have bred endangered species, ______ the giant panda. (ví dụ)", opts:["such as","however","in conclusion"], a:0},
        {q:"______, zoos can be both helpful and harmful for wild animals. (kết luận)", opts:["In conclusion","First","Such as"], a:0}
      ]}
    ]},
    {id:6, icon:"🇻🇳➡️🇬🇧", vn:"Dịch đoạn văn: Cứu hộ động vật hoang dã", en:"Translate: wildlife rescue", blocks:[
      {kind:"theory", title:"🇻🇳➡️🇬🇧 Nguồn đoạn văn", instr:"", html:"Đoạn văn dưới đây trích NGUYÊN VĂN từ báo <b>Sức khỏe & Đời sống</b> (suckhoedoisong.vn – cơ quan ngôn luận của Bộ Y tế), bài <i>\"Vườn quốc gia Bạch Mã cứu hộ, tái thả về tự nhiên nhiều cá thể động vật quý hiếm\"</i> (tác giả Hoàng Dũng, đăng 16/12/2025). Đây là nguồn báo chí chính thống, chủ đề bảo vệ động vật hoang dã khớp với Unit 4 Science."},
      {kind:"passage", title:"🇻🇳 Đoạn văn cần dịch", instr:"", text:"Vườn quốc gia Bạch Mã cứu hộ và tái thả hàng trăm cá thể động vật quý hiếm về tự nhiên trong giai đoạn 2017 - 2025, góp phần bảo tồn đa dạng sinh học rừng. Từ năm 2017, Trung tâm Cứu hộ, bảo tồn và Phát triển sinh vật (thuộc Vườn quốc gia Bạch Mã) thực hiện các hoạt động tiếp nhận và cứu hộ động vật hoang dã do người dân giao nộp hoặc các cơ quan chức năng chuyển giao. Năm 2020, trung tâm tiếp nhận, chăm sóc và tái thả 106 cá thể thuộc 7 loài. Năm 2021, số lượng cá thể được tái thả tăng lên 136 cá thể, thuộc 10 loài. Trong năm 2024, dù số lượng cá thể được tái thả giảm còn 70 cá thể, nhưng mức độ đa dạng loài vẫn được duy trì với 16 loài khác nhau. Công tác cứu hộ và tái thả động vật hoang dã không chỉ góp phần bảo vệ các loài nguy cấp, quý hiếm mà còn nâng cao nhận thức cộng đồng trong việc chung tay bảo vệ thiên nhiên."},
      {kind:"writing", title:"🇬🇧 Dịch đoạn văn trên sang tiếng Anh", instr:"Cố gắng dùng từ vựng/ngữ pháp đã học trong Unit 4: endangered species, in the wild, release into the wild, rescue, câu bị động, hiện tại hoàn thành...", tasks:[
        {prompt:"Dịch cả đoạn văn tiếng Việt ở trên sang tiếng Anh. Không cần dịch từng chữ — quan trọng là đúng ý và dùng đúng từ vựng/ngữ pháp đã học.", sample:"Bach Ma National Park has rescued and released hundreds of rare animals back into the wild between 2017 and 2025, contributing to the conservation of forest biodiversity. Since 2017, the Rescue, Conservation and Species Development Centre (part of Bach Ma National Park) has been receiving and rescuing wild animals handed over by local people or transferred by relevant authorities. In 2020, the centre received, cared for and released 106 individuals from 7 species. In 2021, the number of released individuals increased to 136, from 10 species. In 2024, although the number of released individuals fell to 70, species diversity was still maintained, with 16 different species. Rescuing and releasing wild animals not only helps protect endangered and rare species, but also raises community awareness about working together to protect nature."}
      ]}
    ]},
    {id:7, icon:"👑", vn:"Trận Boss nâng cao: Liên kết + Ngữ pháp + Dịch", en:"Advanced boss", blocks:[
      {kind:"boss", title:"👑 Trận Boss nâng cao: Toàn bộ Unit 4", instr:"", items:[
        {kind:"mcq", q:"Before ______ the vaccine, Jenner tested it carefully.", opts:["giving","give","gave"], a:0},
        {kind:"mcq", q:"Most children ______ against measles and polio.", opts:["are vaccinated","vaccinate","vaccinated"], a:0},
        {kind:"gapfill", s:"We ___________ about DNA all week. (have been learning)", a:"have been learning"},
        {kind:"mcq", q:"Richard's invention ______ him famous.", opts:["has made","have made","has been made"], a:0},
        {kind:"classify", word:"Many lions have been killed by farmers.", ctx:"", cats:["Tiếp diễn","Bị động"], cat:1},
        {kind:"classify", word:"We've been learning about DNA all week.", ctx:"", cats:["Tiếp diễn","Bị động"], cat:0},
        {kind:"mcq", q:"Choose the more objective sentence.", opts:["A study found 60% of large herbivores are at risk.","Everyone who disagrees is just wrong.","People who love animals always agree with me."], a:0},
        {kind:"gapfill", s:"Animals in zoos can suffer ___________ stress. (giới từ)", a:"from"},
        {kind:"mcq", q:"Which connective links CONTRASTING ideas?", opts:["However","In addition","First"], a:0},
        {kind:"gapfill", s:"How do you say 'tái thả về tự nhiên' in English? (2 từ + giới từ)", a:"release into the wild"}
      ]}
    ]}
  ]
}});
