        {kind:"gapfill", s:"A ___ ___ is useful if you can't get close to the animal.", a:"zoom lens"},
        {kind:"classify", word:"Use a tripod to hold the camera steady.", ctx:"", cats:["Mẹo chụp ảnh","Thông tin về cuộc thi"], cat:0},
        {kind:"classify", word:"The competition is open to anyone aged 18 or under.", ctx:"", cats:["Mẹo chụp ảnh","Thông tin về cuộc thi"], cat:1},
        {kind:"gapfill", s:"RSPCA stands for the Royal Society for the Prevention of Cruelty to ___.", a:"animals"},
        {kind:"mcq", q:"'out of focus' nghĩa là gì?", opts:["mất nét, không rõ nét","quá sáng","quá tối"], a:0},
        {kind:"anagram", clue:"hậu cảnh, phông nền", scrambled:"CNKORUGDBA", answer:"background"},
        {kind:"gapfill", s:"Please give each photo a title and write a ___.", a:"description"}
