CG9.addLesson({id:"u6-1", unit:6, type:"lesson", src:"Tho Noi Quy Quest - Cambridge Global English 9 Unit 6.1.html", game:{
  storageKey: "tho-quest-cge9-u61-v1",
  brand: "Thỏ Nội Quy Quest",
  subtitle: "Cambridge Global English 9 – Unit 6.1 School rules",
  mapTitle: "📏 Bản đồ phiêu lưu: Nội quy trường học",
  mapIntro: "Cùng Thỏ khám phá từ vựng về nội quy trường học và ôn lại have to/mustn't + học thể bị động với động từ nguyên mẫu (allowed to/expected to/supposed to) — Unit 6.1, Cambridge Global English 9. Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ dựa theo Cambridge Global English Learner's Book 9 (2nd ed.), Unit 6 Rules and laws, bài 6.1 \"School rules\". Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Unit 6.1 – School rules",
  unlockAll: true,
  vocab: [
    {term:"strict", vi:"nghiêm khắc", ex:"Is your school strict about the rules?"},
    {term:"good behaviour", vi:"cách cư xử tốt", ex:"Good behaviour and respect for other people are important."},
    {term:"respect", vi:"sự tôn trọng", ex:"They have to show respect to their teachers."},
    {term:"break the rules", vi:"vi phạm nội quy", ex:"If you break the rules, you get into trouble."},
    {term:"get into trouble", vi:"gặp rắc rối (do vi phạm)", ex:"You get into trouble if you don't follow the rules."},
    {term:"get a detention", vi:"bị phạt ở lại trường", ex:"If you're late three times, you get a detention."},
    {term:"stay behind after school", vi:"ở lại trường sau giờ học (để bị phạt)", ex:"Students who break the rules sometimes have to stay behind after school."}
  ],
  grammarNotes: [
    {title:"Bị động + động từ nguyên mẫu (allowed to/expected to/supposed to)", body:"Dùng thể bị động của các động từ như allow, encourage, expect, suppose + to + động từ nguyên mẫu để nói về nội quy.\nAt lunch, we're expected to serve the food and drinks for each other.\nWe're not allowed to wear earphones.\nAre you supposed to know all the rules?"},
    {title:"Ôn lại have to / mustn't / don't have to", body:"have to: bắt buộc phải làm — They have to wear the correct school uniform.\nmustn't: bị cấm, không được làm — They mustn't talk in the corridors.\ndon't have to KHÔNG giống mustn't — don't have to nghĩa là không bắt buộc (nhưng vẫn được phép): They don't have to have lunch in the school canteen (họ có thể mang cơm theo nếu muốn)."}
  ],
  levels: [
    {id:1, icon:"📏", vn:"Nối từ vựng nội quy trường học", en:"Match school rules vocabulary", blocks:[
      {kind:"match", title:"📏 Nối từ với nghĩa tiếng Việt", instr:"Bấm 1 từ bên trái, rồi bấm nghĩa đúng bên phải.", pairs:[
        {left:"strict", right:"nghiêm khắc"},
        {left:"good behaviour", right:"cách cư xử tốt"},
        {left:"respect", right:"sự tôn trọng"},
        {left:"break the rules", right:"vi phạm nội quy"},
        {left:"get into trouble", right:"gặp rắc rối"},
        {left:"get a detention", right:"bị phạt ở lại trường"},
        {left:"stay behind after school", right:"ở lại trường sau giờ học"}
      ]}
    ]},
    {id:2, icon:"❓", vn:"Trắc nghiệm từ vựng nội quy", en:"Multiple choice: rules vocabulary", blocks:[
      {kind:"mcq", title:"❓ Chọn đáp án đúng", instr:"", questions:[
        {q:"A school with a lot of firm rules that are strongly enforced is...", opts:["strict","free","boring"], a:0},
        {q:"If you don't follow the rules, you...", opts:["break the rules","get a detention","respect the rules"], a:0},
        {q:"Being punished by having to stay at school after lessons finish is called...", opts:["getting a detention","getting good behaviour","getting respect"], a:0},
        {q:"Treating teachers and classmates politely and fairly shows...", opts:["respect","trouble","detention"], a:0},
        {q:"If you break the rules, you often...", opts:["get into trouble","get good behaviour","get respect"], a:0},
        {q:"Behaving well and following the rules is called...", opts:["good behaviour","strict behaviour","trouble"], a:0},
        {q:"'Stay behind after school' means...", opts:["stay at school after lessons end, as a punishment","go home early","have lunch at school"], a:0}
      ]}
    ]},
    {id:3, icon:"⚙️", vn:"Ngữ pháp: bị động + động từ nguyên mẫu", en:"Grammar: passive + infinitive", blocks:[
      {kind:"theory", title:"⚙️ allowed to / expected to / supposed to / encouraged to", instr:"", html:"Dùng thể bị động của allow, encourage, expect, suppose + <b>to + V (nguyên mẫu)</b> để nói về nội quy:<br>At lunch, we're <b>expected to serve</b> the food and drinks for each other.<br>We're not <b>allowed to wear</b> earphones.<br>Are you <b>supposed to know</b> all the rules?<br>Students are <b>encouraged to ask</b> questions in class."},
      {kind:"gapfill", title:"⚙️ Điền dạng đúng (to + V)", instr:"", items:[
        {pre:"We're not allowed", post:"(use) our phones during lessons.", answers:["to use"]},
        {pre:"Students are expected", post:"(arrive) at school on time.", answers:["to arrive"]},
        {pre:"Are you supposed", post:"(wear) a uniform at your school?", answers:["to wear"]},
        {pre:"Younger students are encouraged", post:"(ask) for help if they need it.", answers:["to ask"]}
      ]}
    ]},
    {id:4, icon:"🎧", vn:"Nghe: phỏng vấn về nội quy trường học", en:"Listening: interview about school rules", blocks:[
      {kind:"passage", title:"🎧 Tóm tắt bài phỏng vấn", instr:"", text:"An interviewer asks some students about the rules at their school. The students explain that they have to wear the correct school uniform and they mustn't talk in the corridors, but they don't have to have lunch in the school canteen — they can bring their own if they like. They're expected to answer teachers politely, and they're not allowed to look out of the window or interrupt when someone is speaking. Overall, the students think the rules help create good behaviour, even though the school is quite strict."},
      {kind:"classify", title:"🎧 Nội quy này là ĐƯỢC PHÉP hay KHÔNG ĐƯỢC PHÉP?", instr:"", cats:["Được phép / phải làm","Không được phép"], items:[
        {word:"Answer teachers politely.", ctx:"", cat:0},
        {word:"Talk in the corridors.", ctx:"", cat:1},
        {word:"Bring your own lunch if you like.", ctx:"", cat:0},
        {word:"Look out of the window during lessons.", ctx:"", cat:1},
        {word:"Interrupt when someone is speaking.", ctx:"", cat:1},
        {word:"Sit up straight in class.", ctx:"", cat:0}
      ]}
    ]},
    {id:5, icon:"🌍", vn:"Nội quy trường học trên thế giới", en:"School rules around the world", blocks:[
      {kind:"theory", title:"🌍 have to / mustn't / don't have to", instr:"", html:"<b>have to:</b> bắt buộc phải làm — They <b>have to</b> wear the correct school uniform.<br><b>mustn't:</b> bị cấm, không được làm — They <b>mustn't</b> talk in the corridors.<br><b>don't have to:</b> không bắt buộc (nhưng vẫn được phép nếu muốn) — They <b>don't have to</b> have lunch in the school canteen."},
      {kind:"gapfill", title:"🌍 Điền have to / mustn't / don't have to đúng dạng", instr:"Chia đúng theo chủ ngữ (has to/have to).", items:[
        {pre:"In Japan, school children", post:"(expect) to help clean and tidy the classrooms at the end of the day.", answers:["are expected"]},
        {pre:"Schools in France", post:"(not/allow) to serve tomato ketchup.", answers:["are not allowed","aren't allowed"]},
        {pre:"At some primary schools in the UK, every student", post:"(encourage) to run a mile before lessons.", answers:["is encouraged"]},
        {pre:"In China, students", post:"(expect) to have a nap at midday.", answers:["are expected"]}
      ]}
    ]},
    {id:6, icon:"✍️", vn:"Viết về nội quy trường em", en:"Writing about your own school rules", blocks:[
      {kind:"writing", title:"✍️ Viết câu của riêng em", instr:"", tasks:[
        {prompt:"Viết 1 câu dùng 'allowed to' hoặc 'not allowed to' nói về nội quy trường em.", sample:"We're not allowed to use our phones during lessons."},
        {prompt:"Viết 1 câu dùng 'expected to' hoặc 'supposed to' nói về điều học sinh trường em phải làm.", sample:"We're expected to arrive at school by 7.30 a.m."},
        {prompt:"Viết 2-3 câu so sánh nội quy trường em với một quy tắc ở nước khác (Nhật/Pháp/Anh/Trung Quốc) mà em vừa học.", sample:"In Japan, school children are expected to clean their classrooms, but at my school we don't have to do that — the school has cleaners."}
      ]}
    ]},
    {id:7, icon:"🗣️", vn:"Luyện nói: Nội quy ở trường em", en:"Speaking: rules at your school", blocks:[
      {kind:"speaking", title:"🗣️ Thẻ luyện nói", instr:"", cards:[
        {q:"Is it possible to have a school without rules? Why / Why not?", vi:"Có thể có một trường học không có nội quy không? Vì sao?", sample:"I don't think so, because rules help keep everyone safe and make sure lessons aren't interrupted."},
        {q:"Are rules important at school? Why?", vi:"Nội quy có quan trọng ở trường không? Vì sao?", sample:"Yes, they are, because they create good behaviour and respect between students and teachers."},
        {q:"Is it ever right to break the rules?", vi:"Có bao giờ đúng khi vi phạm nội quy không?", sample:"Sometimes, if a rule is unfair, but usually it's better to talk to a teacher about it first."},
        {q:"Who should make the rules at a school?", vi:"Ai nên là người đặt ra nội quy ở trường?", sample:"I think teachers and students should make the rules together, so everyone agrees with them."}
      ]}
    ]},
    {id:8, icon:"👑", vn:"Trận Boss: Tổng ôn tập Unit 6.1", en:"Boss battle: Unit 6.1 review", blocks:[
      {kind:"boss", title:"👑 Trận Boss: Tổng ôn tập Unit 6.1", instr:"", items:[
        {kind:"mcq", q:"'get a detention' nghĩa là gì?", opts:["bị phạt ở lại trường","được khen thưởng","nghỉ học"], a:0},
        {kind:"mcq", q:"'strict' nghĩa là gì?", opts:["nghiêm khắc","dễ dãi","vui vẻ"], a:0},
        {kind:"gapfill", s:"We're not allowed ___ (use) our phones in class.", a:"to use"},
        {kind:"classify", word:"Talk in the corridors.", ctx:"", cats:["Được phép","Không được phép"], cat:1},
        {kind:"classify", word:"Answer teachers politely.", ctx:"", cats:["Được phép","Không được phép"], cat:0},
        {kind:"gapfill", s:"In Japan, school children ___ ___ (expect) to clean the classrooms.", a:"are expected"},
        {kind:"mcq", q:"Chọn câu đúng: 'don't have to' nghĩa là gì?", opts:["không bắt buộc, nhưng vẫn được phép nếu muốn","bị cấm hoàn toàn","luôn luôn phải làm"], a:0},
        {kind:"anagram", clue:"sự tôn trọng", scrambled:"CTRSEPE", answer:"respect"},
        {kind:"gapfill", s:"They ___ (mustn't/have to) talk in the corridors. (chọn từ đúng)", a:"mustn't"}
      ]}
    ]}
  ]
}});
CG9.addLesson({id:"u8-5", unit:8, type:"lesson", src:"Tho Nong Trai Quest - Cambridge Global English 9 Unit 8.5.html", game:{
  storageKey: "tho-quest-cge9-u85-v1",
  brand: "Thỏ Nông Trại Quest",
  subtitle: "Cambridge Global English 9 – Unit 8.5 Living and growing",
  mapTitle: "🌱 Bản đồ phiêu lưu: Sống và trồng trọt",
  mapIntro: "Cùng Thỏ khám phá nông nghiệp đô thị, thủy canh, và khu vườn nổi của người Aztec — Unit 8.5, Cambridge Global English 9. Tất cả các màn đều MỞ SẴN!",
  footer: "Tự soạn cho bé Thỏ dựa theo Cambridge Global English Learner's Book 9 (2nd ed.), Unit 8 The environment, bài 8.5 \"Living and growing\". Tiến độ lưu trên trình duyệt này. Tất cả các màn đều mở khoá ngay từ đầu.",
  notebookTitle: "📖 Sổ tay Unit 8.5 – Living and growing",
  unlockAll: true,
  vocab: [
    {term:"consumer", vi:"người tiêu dùng", ex:"Urban farming means produce is delivered quickly to consumers."},
    {term:"food production", vi:"sản xuất lương thực", ex:"Farming helps city dwellers reconnect with food production."},
    {term:"hydroponics", vi:"thuỷ canh (trồng cây không cần đất)", ex:"Plants are grown without soil, using hydroponics."},
    {term:"nitrogen", vi:"ni-tơ (đạm)", ex:"Corn takes nitrogen from the soil, which beans then replace."},
    {term:"nutrient", vi:"dưỡng chất", ex:"Plants receive the correct amount of light, water and nutrients."},
    {term:"supply chain", vi:"chuỗi cung ứng", ex:"Growing food in the city means a much simpler supply chain."},
    {term:"vertical farming", vi:"canh tác theo chiều dọc (nhà kính nhiều tầng)", ex:"Old warehouses have been converted to accommodate vertical farming."},
    {term:"to repurpose", vi:"tái sử dụng cho mục đích khác", ex:"Cities are repurposing the roofs of buildings to make vegetable farms."}
  ],
  grammarNotes: [
    {title:"Nông nghiệp đô thị hiện đại", body:"Cities like Shanghai, Singapore, Rotterdam and Paris are repurposing rooftops, old factories, warehouses and even underground tunnels for growing food. 'Vertical farming' uses hydroponics: plants are grown without soil, receiving the exact light, water and nutrients they need — so less water, less space and no pesticides are needed."},
    {title:"Vườn nổi Chinampa của người Aztec", body:"Hơn 500 năm trước, người Aztec ở Tenochtitlan trồng ngô, đậu và bí trên các đảo nổi nhân tạo gọi là chinampas. Lá bí to giữ ẩm và diệt cỏ dại; ngô lấy nitrogen (đạm) từ đất, rồi đậu bổ sung lại nitrogen đó — nên các loại cây được trồng luân phiên (crop rotation)."}
  ],
  levels: [
    {id:1, icon:"🌱", vn:"Nối từ vựng nông nghiệp đô thị", en:"Match urban farming vocabulary", blocks:[
      {kind:"match", title:"🌱 Nối từ với nghĩa tiếng Việt", instr:"Bấm 1 từ bên trái, rồi bấm nghĩa đúng bên phải.", pairs:[
        {left:"consumer", right:"người tiêu dùng"},
        {left:"food production", right:"sản xuất lương thực"},
        {left:"hydroponics", right:"thuỷ canh"},
        {left:"nitrogen", right:"ni-tơ (đạm)"},
        {left:"nutrient", right:"dưỡng chất"},
        {left:"supply chain", right:"chuỗi cung ứng"},
        {left:"vertical farming", right:"canh tác theo chiều dọc"},
        {left:"to repurpose", right:"tái sử dụng cho mục đích khác"}
      ]}
    ]},
    {id:2, icon:"❓", vn:"Trắc nghiệm từ vựng", en:"Multiple choice: vocabulary", blocks:[
      {kind:"mcq", title:"❓ Chọn đáp án đúng", instr:"", questions:[
        {q:"'Hydroponics' means growing plants...", opts:["without soil, using water with nutrients","only in very hot climates","only on rooftops"], a:0},
        {q:"A 'supply chain' is...", opts:["the process of getting food from producer to consumer","a type of fertiliser","a farming tool"], a:0},
        {q:"'Vertical farming' means...", opts:["growing food in stacked layers, often indoors","growing food only underground","growing food in a single flat field"], a:0},
        {q:"To 'repurpose' a building means to...", opts:["find another use for it","demolish it","paint it a new colour"], a:0},
        {q:"A 'consumer' is someone who...", opts:["buys and uses goods, like food","grows food to sell","delivers food to shops"], a:0}
      ]}
    ]},
    {id:3, icon:"🏙️", vn:"Lý thuyết: nông nghiệp đô thị", en:"Theory: urban farming today", blocks:[
      {kind:"theory", title:"🏙️ Trồng rau trên mái nhà & vertical farming", instr:"", html:"Các thành phố như Shanghai, Singapore, Rotterdam và Paris đang <b>repurpose</b> (tái sử dụng) mái nhà của các toà văn phòng, chung cư và nhà kho để làm vườn rau.<br>Nhà máy cũ, kho bỏ hoang, thậm chí đường hầm tàu điện ngầm bỏ hoang cũng được chuyển đổi thành <b>vertical farming</b> — dùng <b>hydroponics</b>: cây được trồng không cần đất, nhận đúng lượng ánh sáng, nước và <b>nutrients</b> cần thiết."},
      {kind:"gapfill", title:"🏙️ Điền từ đúng", instr:"", items:[
        {pre:"Cities are", post:"(repurpose) rooftops to grow vegetables.", answers:["repurposing"]},
        {pre:"Vertical farming uses", post:"(hydroponics) — plants grown without soil.", answers:["hydroponics"]},
        {pre:"Plants receive the correct amount of light, water and", post:"(nutrients).", answers:["nutrients"]},
        {pre:"Because growing conditions are controlled, pesticides are not", post:"(necessary).", answers:["necessary"]}
      ]}
    ]},
    {id:4, icon:"📖", vn:"Đọc: vườn nổi Chinampa của người Aztec", en:"Reading: the Aztec chinampas", blocks:[
      {kind:"passage", title:"📖 Tóm tắt bài đọc", instr:"", text:"Urban farming is not an entirely new idea. Over 500 years ago, Tenochtitlan (modern-day Mexico City) was one of the largest cities in the world, with more than 250,000 people. To feed the city, farmers grew crops on human-made floating islands called chinampas. The main crops were corn, beans and squash, which grow well together: the large leaves of the squash keep in moisture and keep weeds out, and corn takes nitrogen from the soil, which beans then replace, so the main crops were grown in rotation. The Aztecs grew many other vegetables too, including tomatoes, avocados, chilli peppers, limes, peanuts and sweet potatoes. Today, organic salad crops are still grown on these same floating islands. Growing food in the city for the city means a much simpler supply chain, less food waste, and lower transport costs and emissions."},
      {kind:"classify", title:"📖 Chi tiết này thuộc NÔNG NGHIỆP ĐÔ THỊ HIỆN ĐẠI hay VƯỜN NỔI AZTEC?", instr:"", cats:["Nông nghiệp đô thị hiện đại","Vườn nổi Aztec (chinampas)"], items:[
        {word:"vertical farming using hydroponics", ctx:"", cat:0},
        {word:"repurposing old factories and warehouses", ctx:"", cat:0},
        {word:"floating islands in Tenochtitlan", ctx:"", cat:1},
        {word:"corn, beans and squash grown together", ctx:"", cat:1},
        {word:"willow trees anchoring the islands to the lake bed", ctx:"", cat:1},
        {word:"rooftop vegetable farms in Shanghai and Paris", ctx:"", cat:0}
      ]}
    ]},
    {id:5, icon:"🌽", vn:"Lý thuyết: trồng xen canh & luân canh", en:"Theory: companion planting & crop rotation", blocks:[
      {kind:"theory", title:"🌽 Corn, beans and squash grow well together", instr:"", html:"Ngô, đậu và bí là 3 loại cây trồng chính của người Aztec, chúng phát triển tốt khi trồng cùng nhau:<br>Lá bí (squash) to giúp giữ độ ẩm trong đất và ngăn cỏ dại mọc.<br>Ngô (corn) lấy <b>nitrogen</b> từ đất; đậu (beans) sau đó bổ sung lại nitrogen cho đất — vì vậy các cây được trồng <b>luân phiên</b> (in rotation)."},
      {kind:"gapfill", title:"🌽 Điền từ đúng", instr:"", items:[
        {pre:"The large leaves of the squash keep in", post:"(moisture) and keep weeds out.", answers:["moisture"]},
        {pre:"Corn takes", post:"(nitrogen) from the soil.", answers:["nitrogen"]},
        {pre:"Beans then", post:"(replace) the nitrogen that corn has taken.", answers:["replace"]},
        {pre:"So the main crops were grown in", post:"(rotation).", answers:["rotation"]}
      ]}
    ]},
    {id:6, icon:"✍️", vn:"Viết về nông nghiệp đô thị", en:"Writing about urban farming", blocks:[
      {kind:"writing", title:"✍️ Viết câu của riêng em", instr:"", tasks:[
        {prompt:"Viết 1 câu nói về lợi ích của việc trồng rau trên mái nhà trong thành phố.", sample:"Growing vegetables on rooftops gives city dwellers a simpler supply chain and fresher food."},
        {prompt:"Viết 1 câu dùng từ 'hydroponics' hoặc 'vertical farming'.", sample:"Vertical farming using hydroponics needs less water and space than traditional farming."},
        {prompt:"Viết 2-3 câu so sánh vườn nổi Aztec với nông nghiệp đô thị hiện đại.", sample:"The Aztecs grew corn, beans and squash together on floating islands. Today, cities use vertical farming and hydroponics instead, but the goal of growing food close to consumers is the same."}
      ]}
    ]},
    {id:7, icon:"🗣️", vn:"Luyện nói: nông nghiệp đô thị", en:"Speaking: urban farming", blocks:[
      {kind:"speaking", title:"🗣️ Thẻ luyện nói", instr:"", cards:[
        {q:"What are the advantages of urban farming and gardening for the environment?", vi:"Nông nghiệp đô thị mang lại lợi ích gì cho môi trường?", sample:"It gives a simpler supply chain, less food waste, and lower transport costs and emissions."},
        {q:"Are there any disadvantages of urban farming?", vi:"Nông nghiệp đô thị có nhược điểm gì không?", sample:"It might need a lot of investment in technology like hydroponics, and rooftop space is limited."},
        {q:"How do farming and gardening in the city help the people who live there?", vi:"Việc trồng trọt trong thành phố giúp gì cho người dân sống ở đó?", sample:"They help people reconnect with food production and value fresh food, which can improve well-being and mental health."},
        {q:"What did the Aztecs know about crops that grow well together?", vi:"Người Aztec biết gì về việc trồng xen các loại cây?", sample:"They knew that corn, beans and squash grow well together because the squash keeps in moisture and beans replace the nitrogen that corn takes from the soil."}
      ]}
    ]},
    {id:8, icon:"👑", vn:"Trận Boss: Tổng ôn tập Unit 8.5", en:"Boss battle: Unit 8.5 review", blocks:[
      {kind:"boss", title:"👑 Trận Boss: Tổng ôn tập Unit 8.5", instr:"", items:[
        {kind:"mcq", q:"'Hydroponics' nghĩa là gì?", opts:["trồng cây không cần đất, dùng nước có dưỡng chất","trồng cây chỉ ngoài trời","một loại phân bón"], a:0},
        {kind:"mcq", q:"'Supply chain' nghĩa là gì?", opts:["chuỗi cung ứng","một loại cây trồng","hệ thống tưới nước"], a:0},
        {kind:"gapfill", s:"Cities are ___ (repurpose) rooftops to grow vegetables.", a:"repurposing"},
        {kind:"classify", word:"floating islands in Tenochtitlan (chinampas)", ctx:"", cats:["Nông nghiệp đô thị hiện đại","Vườn nổi Aztec"], cat:1},
        {kind:"classify", word:"vertical farming using hydroponics", ctx:"", cats:["Nông nghiệp đô thị hiện đại","Vườn nổi Aztec"], cat:0},
        {kind:"gapfill", s:"Corn takes ___ (nitrogen) from the soil, which beans then replace.", a:"nitrogen"},
        {kind:"mcq", q:"'Vertical farming' nghĩa là gì?", opts:["canh tác theo chiều dọc, nhiều tầng","canh tác dưới nước","canh tác chỉ vào mùa đông"], a:0},
        {kind:"anagram", clue:"người tiêu dùng", scrambled:"NCOSMEUR", answer:"consumer"},
        {kind:"gapfill", s:"The large leaves of the squash keep in ___ (moisture) and keep weeds out.", a:"moisture"}
      ]}
    ]}
  ]
}});
