        {kind:"mcq", q:"'petition' nghĩa là gì?", opts:["bản kiến nghị","tấm biển cầm tay","vấn đề"], a:0},
        {kind:"gapfill", s:"Thousands of students ___ ___ ___ (go on strike) to protest.", a:"went on strike"},
        {kind:"gapfill", s:"There were almost 200 ___ across the country.", a:"demos"},
        {kind:"classify", word:"\"Teenage rage\"", ctx:"tiêu đề báo 1", cats:["Tiêu cực","Tích cực"], cat:0},
        {kind:"classify", word:"\"protested peacefully\"", ctx:"", cats:["Tiêu cực","Tích cực"], cat:1},
        {kind:"anagram", clue:"thái độ", scrambled:"EUTTDATI", answer:"attitude"},
        {kind:"anagram", clue:"ấn tượng", scrambled:"OIPMSSNERI", answer:"impression"},
        {kind:"mcq", q:"'issue' nghĩa là gì?", opts:["vấn đề quan trọng","cơn giận dữ","tấm biển"], a:0}
